if(window.__ML_EXPEDITION10__)return;window.__ML_EXPEDITION10__=true;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const BASE='expedition10/',ART=BASE+'art/',SC=ART+'scenes/',CREW=ART+'crew/';
