const L=window.ML10Logic;
const stages=[
 {id:'ml10_01',name:'قفل المنارة',place:'منارة الشاطئ الذهبي',kind:'استنتاج رقمي',scene:'01-lighthouse.webp',prop:'treasure/art/story5/ch1_s1_piece_lock_slider.webp',objective:'اكتشف الرمز المكوّن من ثلاثة أرقام لفتح عدسة المنارة وإعادة النور إلى الممر.',story:'وصلت رواء ونهى وورد إلى منارة أَثْران. في بابها قفل نحاسي لا يفتح بالقوة؛ كل محاولة تكشف معلومة دقيقة عن الرمز.',moods:['thinking','curious','alert'],talk:['الرمز ليس عشوائياً؛ سأقارن الشفرات وأستبعد المستحيل.','هذه آلية قديمة… أسمع التروس تتحرك خلف القفل!','سأقرأ النقوش حول الباب؛ ربما تخفي دليلاً لا نراه.'],hint:['ابدأ بالدليل الذي يقول إن الأرقام الثلاثة في المحاولة غير موجودة في الرمز.','الرقم ٢ في المحاولة ٢٠٦ موجود لكنه ليس في الخانة الأولى ولا الثانية؛ مكانه الأخير.','الرمز هو ٠٤٢.'],outro:'عاد شعاع المنارة إلى البحر، وكشف ممراً حجرياً يصل إلى معبر النهر.'},
 {id:'ml10_02',name:'معبر النهر',place:'ممر الشلالات',kind:'تخطيط مسار',scene:'02-river.webp',prop:'treasure/art/story5/ch3_s1_piece_boat.webp',objective:'أوصل القارب إلى الضفة المقابلة، واختر الممر الوحيد الذي لا ينتهي بطريق مسدود.',story:'تحرس الشلالات ممراً ضيقاً. رسمت ورد مسارات صغيرة على الخريطة، لكن ثلاثة منها تنتهي بين الصخور.',moods:['alert','thinking','curious'],talk:['راقب تفرعات الطريق؛ ليس كل ممر يصل إلى الضفة.','سأفحص الجسور، بعض الألواح ثابت وبعضها يقود إلى طريق مسدود.','أرى علامات الماء على الصخور… اتبع المسار الذي يواصل الجريان.'],hint:['يمكنك الرجوع خطوة بالضغط على آخر عقدة وصلت إليها.','المسار الآمن يمر بالمحطة الزرقاء ثم القوس الحجري ثم الرصيف.','المسار الوحيد: المرسى ← النخلة ← الصخرة ← القوس ← البرج ← الرصيف ← الضفة.'],outro:'عبر القارب بسلام، وعثرت الشخصيات على قطع خريطة ممزقة.'},
 {id:'ml10_03',name:'الخريطة الممزقة',place:'ساحة الخرائط القديمة',kind:'تركيب مكاني',scene:'03-map.webp',prop:'treasure/art/story5/ch2_s1_piece_map_fragment.webp',objective:'أعد تركيب القطع الأربع. يجب أن تتطابق النقوش الداخلية، وتبقى الحواف الفارغة على أطراف الخريطة.',story:'في ساحة الخرائط، ترك قبطان مجهول أربع رقع تحمل خطوطاً متصلة. إن اجتمعت النهايات المتشابهة، ظهر طريق الجزيرة التالية.',moods:['curious','thinking','happy'],talk:['سأبحث عن القطعة التي لا تملك وصلة على الحافة اليسرى أو العليا.','النقوش تعمل مثل الدوائر الكهربائية؛ كل طرف يحتاج إلى قرينه.','احتفظ بالقطع التي تتصل أطرافها، ولا تضع وصلة داخلية على طرف الخريطة.'],hint:['القطعة ذات الوصلة A على اليمين مكانها أعلى اليسار.','بعد تثبيت أعلى اليسار، ضع القطعة التي تحمل A على اليسار في أعلى اليمين.','الترتيب الصحيح: ١ ثم ٢ في الأعلى، ٣ ثم ٤ في الأسفل.'],outro:'اكتملت الخريطة وأشارت إلى مخزن القراصنة حيث يختبئ ميزان قديم.'},
 {id:'ml10_04',name:'ميزان القراصنة',place:'مخزن الذهب الغارق',kind:'استدلال وقياس',scene:'04-balance.webp',prop:'treasure/art/story5/ch3_s2_piece_balance_pan.webp',objective:'بين تسع قطع متطابقة، توجد قطعة واحدة أثقل. استخدم وزنتين فقط ثم حدّد القطعة.',story:'وجدت نهى ميزاناً دقيقاً وتسع قطع ذهبية. واحدة أثقل قليلاً من البقية. لا تكفي العين؛ لا بد من خطة وزن ذكية.',moods:['thinking','happy','curious'],talk:['سأقسم القطع إلى مجموعات متساوية؛ كل وزنة يجب أن تعطينا أكبر معلومة.','الميزان يعمل. لا نحتاج إلى وزن القطع واحدة واحدة.','إن اتزنت الكفتان، فابحث في القطع التي بقيت خارج الميزان.'],hint:['في الوزنة الأولى ضع ٣ قطع مقابل ٣.','إذا اتزنت الكفتان فالثقيلة بين الثلاث الباقية؛ وإذا مالت كفة فهي ضمنها.','في الوزنة الثانية قارن قطعتين من المجموعة المرشحة؛ وإذا اتزنتا فالثالثة هي الثقيلة.'],outro:'أخرجت القطعة الأثقل مفتاحاً صغيراً محفوراً عليه رمز البلورة.'},
 {id:'ml10_05',name:'ذاكرة البلورات',place:'كهف البلور الأزرق',kind:'ذاكرة تسلسلية',scene:'05-crystal.webp',prop:'treasure/art/story5/ch4_seal_crystal.webp',objective:'احفظ ترتيب الرموز الذي يضيء في البلورات، ثم أعد إدخاله بالترتيب نفسه.',story:'في الكهف، تومض البلورات بتتابع قصير. كل ومضة تحمل رمزاً، لكن الضوء ينطفئ سريعاً ولا يبقى إلا ما تحفظه ذاكرتك.',moods:['happy','curious','thinking'],talk:['سأعيد عرض الومضات إذا احتجت، لكن حاول أن تحفظها من المرة الأولى.','أستطيع تمييز ترتيب الوميض من انعكاسه في البلورة.','سأراقب الرمز الأخير؛ غالباً ما يختلط على المستكشفين.'],hint:['قسّم التسلسل إلى مجموعتين: أول ثلاثة رموز ثم آخر رمزين.','قل الرموز بصوتك أو اربط كل رمز بصورة في ذهنك.','يمكنك إعادة عرض التسلسل من دون خسارة المحاولة.'],outro:'استجابت البلورات لتسلسلك، وانفتح باب يؤدي إلى كهف المرايا.'},
 {id:'ml10_06',name:'مرايا الكهف',place:'ممر الانعكاسات',kind:'اتجاهات مكانية',scene:'06-mirror.webp',prop:'treasure/art/story5/ch1_s3_piece_mirror.webp',objective:'أدر المرايا الثلاث حتى ينعكس شعاع المنارة من المصدر إلى العدسة الأخيرة.',story:'تحت الكهف شبكة مرايا نحاسية. الشعاع لا يصل إلى العدسة إلا إذا استقرت كل مرآة على اتجاهها الصحيح.',moods:['thinking','curious','alert'],talk:['سأتتبع الشعاع من المصدر إلى العدسة، مرآة بعد مرآة.','كل ضغطة تدير المرآة ربع دورة؛ راقب اتجاهها.','الخط الذهبي هو مسار الضوء، لا تتركه ينقطع عند أي مرآة.'],hint:['الشمس تشرق من الشرق؛ استخدمها لتحديد اتجاه المرآة الأولى.','المرآة الثانية تواجه عكس اتجاه الأولى.','الثالثة ربع دورة مع عقارب الساعة من الأولى؛ يصبح الترتيب شرق، غرب، جنوب.'],outro:'وصل الشعاع إلى العدسة، وظهر نقش ساعة رملية على الجدار.'},
 {id:'ml10_07',name:'ساعة الرمل',place:'ورشة الزمن',kind:'ترتيب تحت ضغط الوقت',scene:'07-hourglass.webp',prop:'treasure/art/story5/ch5_s2_piece_gear_large.webp',objective:'رتّب الأدوات الخمس بحسب الأدلة قبل أن ينتهي الوقت.',story:'بدأ الرمل يتسرب من ساعة عملاقة. رتّب الأدوات لتفتح باب الورشة قبل أن يصل الرمل إلى العلامة الحمراء.',moods:['thinking','happy','curious'],talk:['لدينا وقت كافٍ إن رتبنا الأدلة ولم نتسرع.','الرمل يتحرك… سأراقب الساعة وأرتب الأدوات بسرعة.','لا تنسَ أن بعض الأدوات يجب أن تأتي مباشرة بعد الأخرى.'],hint:['الخريطة تسبق البوصلة.','البوصلة تأتي مباشرة قبل الفانوس.','الترتيب الكامل: الخريطة، البوصلة، الفانوس، المنظار، المفتاح.'],outro:'توقفت ساعة الرمل، وفتحت الورشة بوابتها إلى شبكة الجزر.'},
 {id:'ml10_08',name:'شبكة الجزر',place:'أرخبيل الممرات السبعة',kind:'تصميم شبكة بأقل كلفة',scene:'08-islands.webp',prop:'treasure/art/story5/ch3_s1_piece_tide_lever.webp',objective:'اربط الجزر الست بخمسة حبال فقط، واجعل الشبكة متصلة بالكامل دون تجاوز ميزانية ١٥ علامة حبل.',story:'تحتاج الجزر إلى شبكة مراسٍ قبل أن تعبر السفينة. كل حبل يستهلك طولاً مختلفاً؛ يجب أن تتصل الجزر كلها بأقل كلفة ممكنة.',moods:['thinking','curious','alert'],talk:['سأبحث عن الروابط القصيرة أولاً ثم أتأكد أن الشبكة كلها متصلة.','لا نريد حلقة زائدة؛ خمسة حبال تكفي لربط ست جزر.','إذا اخترنا رابطاً طويلاً بلا داعٍ فلن تكفي الميزانية لبقية الشبكة.'],hint:['الشبكة تحتاج خمسة روابط بالضبط لست جزر، ومن دون جزيرة معزولة.','ابدأ بأقصر رابط، ثم أضف أقصر رابط يصل جزيرة غير متصلة بالشبكة.','الروابط الوحيدة التي تحقق أقل كلفة: ١، ٢، ٣، ٤، ٥؛ مجموعها ١٥.'],outro:'اكتملت شبكة المراسي بأقل كلفة، وانفتح الطريق إلى مكتبة القبطان.'},
 {id:'ml10_09',name:'المكتبة المفقودة',place:'أرشيف القبطان',kind:'استنتاج نمط شبكي',scene:'09-library.webp',prop:'treasure/art/story5/icon_journal.webp',objective:'أعد إظهار الرمز المخفي في صفحة القبطان. أرقام الصفوف والأعمدة تحدد مجموعات الخانات المضيئة المتجاورة.',story:'في المكتبة، وجدت ورد صفحة ممزقة لا يظهر منها سوى أرقام على الحواف. الأرقام تكشف عدد الخانات المضيئة المتجاورة في كل صف وعمود.',moods:['curious','thinking','happy'],talk:['سأقارن أرقام الحواف؛ كل رقم يصف كتلة متصلة من الخانات.','يمكنني البدء بالعمود الذي يملك ثلاث خانات متجاورة.','سأستخدم الصفوف والأعمدة معاً؛ لا يكفي تخمين شكل الرمز.'],hint:['العمود الثالث رقمه ٣؛ إذن خاناته الثلاث الأولى مضيئة ومتجاورة.','الصفان الأول والثالث لكل منهما ثلاث خانات متصلة، أما الصف الرابع ففيه خانة واحدة.','النمط الوحيد: ١١١٠ / ٠٠١١ / ١١١٠ / ٠١٠٠.'],outro:'اكتمل نقش الأرشيف وظهر رمز يفتح بوابة قلب أَثْران.'},
 {id:'ml10_10',name:'بوابة قلب أَثْران',place:'القبة المركزية',kind:'مواجهة استنتاجية',scene:'10-heart.webp',prop:'treasure/art/story5/ch7_seal_dawn.webp',objective:'صل النجوم الست بالمسار الصحيح لتفعيل قلب الجزيرة وفتح الفصل التالي.',story:'تجتمع إشارات المنارة والخريطة والبلورات في قبة واحدة. أمامك ست نجوم، ولا يضيء القلب إلا إذا اتصلت بالترتيب الذي تركه حراس الجزيرة.',moods:['thinking','alert','happy'],talk:['هذه هي الخريطة التي كنا نبحث عنها؛ سأقود ترتيب النجوم.','تزامنت الآلات أخيراً. بقي أن نصل الضوء إلى القلب.','كل نجمة تفتح الخطوة التالية؛ لا تقفز فوق أي علامة.'],hint:['ابدأ بالنجم الشمالي، ثم اتجه غرباً.','من الغرب انتقل إلى الجنوب الغربي، ثم الجنوب الشرقي.','المسار: الشمال، الغرب، الجنوب الغربي، الجنوب الشرقي، الشرق، الجنوب.'],outro:'اشتعل قلب أَثْران وعادت الأضواء إلى الجزر. انتهى الفصل الأول، وانكشف على الأفق قصر المرايا.'},
 {id:'ml10_11',name:'أنابيب المد',place:'ورشة قنوات الميناء',kind:'تركيب مسار مائي',scene:'11-pipes.webp',prop:'watercolor/art/icons54/lever.webp',objective:'دوّر قطع الأنابيب السبع حتى يصل الماء من المدخل إلى المصب، مع اتصال كل وصلة وعدم ترك أي طرف مفتوح.',story:'وجدت نهى شبكة قنوات قديمة تحت الميناء. الماء محبوس خلف سبع قطع دوارة، وكل وصلة يجب أن تقابل الأنبوب المجاور بدقة.',moods:['thinking','curious','alert'],talk:['سأبدأ من المدخل وأتبع الانعطاف قطعةً قطعة.','أستطيع سماع الماء خلف الجدار؛ لا بد أن اتجاه إحدى الوصلات معكوس.','راقب أطراف الأنبوب؛ الطرف المفتوح يعني أن الماء سيتسرب.'],hint:['المسار ينزل بعد القطعة الأولى، ثم ينعطف شرقاً في أسفل اللوحة.','القطع المستقيمة عمودية في الموضعين الثاني والسادس، وأفقية في الوسط.','اتجاهات القطع بالترتيب: جنوب-غرب، عمودي، شمال-شرق، أفقي، شمال-غرب، عمودي، جنوب-شرق.'],outro:'اندفع الماء في القناة، وفتح باباً جليدياً خلف الشلال.'},
 {id:'ml10_12',name:'ممر الجليد',place:'كهف البلور المتجمد',kind:'تخطيط انزلاقي من سبع حركات',scene:'12-ice.webp',prop:'watercolor/art/icons54/crystal.webp',objective:'حرّك بلورة القارب فوق الجليد. لا تتوقف في منتصف الطريق؛ تنزلق حتى يصطدم المسار بصخرة أو حافة. أوصلها إلى البوابة في سبع حركات بالضبط.',story:'في الكهف المتجمد لا تستطيع البلورة التوقف بإرادتك؛ سطح الجليد يدفعها حتى تصطدم بعائق. على رواء قراءة حدود المسار قبل كل انزلاق.',moods:['alert','thinking','curious'],talk:['لا تدفع البلورة عشوائياً؛ فكّر أين ستتوقف قبل أن تتحرك.','سأرسم في ذهني مواضع الصخور؛ كل صخرة تصنع نقطة توقف جديدة.','سبع حركات فقط تفتح البوابة، وأي التفاف زائد يضيّع المسار.'],hint:['البلورة تبدأ أسفل اليسار، والصخور الداكنة هي العوائق.','الحركة الأولى إلى اليمين، ثم إلى أعلى.','المسار الوحيد الأقصر: يمين، أعلى، يسار، أسفل، يمين، أعلى، يمين.'],outro:'وصلت البلورة إلى البوابة، وخلفها قاعة رهان حراشف التنين.'},
 {id:'ml10_13',name:'رهان حراشف التنين',place:'قاعة الرهان القديمة',kind:'استراتيجية نيم',scene:'13-dragon.webp',prop:'treasure/art/story5/ch3_s2_piece_stone.webp',objective:'أمامك ثلاث أكوام من الحراشف: ١ و٣ و٥. في كل دور خذ من كومة واحدة أي عدد من ١ حتى كامل الكومة. من يأخذ آخر حرشفة يفوز. العب ضد حارس القاعة واختر افتتاحية تضمن لك استراتيجية رابحة.',story:'حارس القاعة لا يقبل التخمين؛ يضع الحراشف في ثلاث أكوام ويعرف كيف يستغل أي حركة متسرعة. عليك أن تترك له وضعاً لا يملك منه استراتيجية رابحة.',moods:['thinking','curious','alert'],talk:['لا أريد أكبر عدد من الحراشف؛ أريد أن أترك للحارس وضعاً خاسراً.','سأحسب الأكوام معاً، لا كل كومة على حدة.','إن أحسنت الافتتاحية، فسيضطر الحارس إلى كشف ثغرة في كل رد.'],hint:['فكّر في قيمة الأكوام معاً، لا في مجموعها الحسابي فقط.','حاول أن تجعل ناتج XOR للأكوام صفراً بعد حركتك.','الافتتاحية الرابحة الوحيدة: خذ ثلاث حراشف من الكومة الثالثة، فتصبح الأكوام ١ و٣ و٢.'],outro:'احترم الحارس ذكاءك وترك لك ختماً قديماً يفتح مسرح الظلال.'},
 {id:'ml10_14',name:'مسرح الظلال',place:'معبد النقوش الضوئية',kind:'استنتاج ظلي واتجاهي',scene:'14-shadows.webp',prop:'treasure/art/story5/tool_lens.webp',objective:'اضبط الفوانيس الثلاثة حتى تطابق ظلالها النقوش على الجدار: سفينة، سلحفاة، ومرساة. اقرأ علاقة اتجاه كل فانوس بالآخر.',story:'في المعبد لا تظهر النقوش مباشرة؛ لا يقرأها إلا من يوجه الضوء من الزاوية الصحيحة. لكل فانوس ظل مختلف، وترتيبها مرتبط ببعضه.',moods:['curious','thinking','alert'],talk:['سأقارن الظلال بالنقوش، ثم أتحقق من علاقة الاتجاهات.','إذا غيّرنا فانوساً واحداً فقد تتغير صورة الجدار كلها.','الضوء يكشف الحقيقة، لكن ترتيب مصادره هو مفتاحها.'],hint:['الفانوس الأول يجب أن يصنع ظل السفينة.','الفانوس الثاني عكس اتجاه الأول تماماً.','الفانوس الثالث ربع دورة مع عقارب الساعة من الأول؛ الاتجاهات النهائية جنوب، شمال، غرب.'],outro:'اصطفّت الظلال الثلاثة، وظهر ختم يحمل رسالة في زجاجة.'},
 {id:'ml10_15',name:'رسالة الزجاجة',place:'مرسى القبطان الأخير',kind:'فك شفرة قيصرية عربية',scene:'15-bottle.webp',prop:'treasure/art/story5/ch1_secret_letter.webp',objective:'أدر قرص الشفرة حتى تتحول الرسالة إلى كلمة مفهومة. استخدم ترتيب الحروف العربية والقرينة المحفورة على عنق الزجاجة.',story:'وصلت زجاجة إلى المرسى تحمل حروفاً غير مفهومة وقرينة واحدة: الحرف ا في الرسالة الأصلية أصبح ج في الشفرة. فك الإزاحة لتعرف اسم المكان الذي يجب أن تقصده الرحلة.',moods:['curious','thinking','happy'],talk:['القرص لا يبدّل الحروف عشوائياً؛ كل حرف يتحرك بالمقدار نفسه.','سأثبت الحرف الأول من القرينة، ثم أختبر بقية الرسالة.','إذا ظهرت كلمة الميناء، نكون قد قرأنا رسالة القبطان كاملة.'],hint:['قارن الحرف ا في الأصل بالحرف ج في النص المشفر.','في ترتيب القرص المعروض، ج يبعد أربع خطوات عن ا.','أدر القرص إلى الإزاحة ٤؛ ستظهر كلمة الميناء.'],outro:'انكشفت رسالة القبطان: الطريق إلى الميناء القديم، حيث تنتظر خمس محطات أخيرة قبل بوابة قصر المرايا.'},
 {id:'ml10_16',name:'سجل الحمولة',place:'ساحة شحن الميناء القديم',kind:'استنتاج وربط قيود',scene:'16-harbor-cargo.webp',prop:'watercolor/art/icons54/boat.webp',objective:'رتّب الصناديق الأربعة على الأرصفة وفق القرائن. لا يوجد صندوقان في الرصيف نفسه، وكل دليل يضيّق موضع الحمولة.',story:'كشفت رسالة القبطان أن مفتاح قصر المرايا أُخفي داخل شحنة لم تغادر الميناء. أمام البطلات أربعة صناديق وأربعة أرصفة، وسجل الشحن ممزق إلى ثلاث قرائن.',moods:['thinking','curious','alert'],talk:['سأقارن ترتيب الصناديق؛ كل قرينة يجب أن تنطبق مع الأخريين.','أستطيع تمييز البلور من لمعانه، لكن لا بد أن نعرف الرصيف الصحيح.','سأراجع سجل الحمولة قبل أن نرسل الصناديق إلى السفينة.'],hint:['صندوق البلور يسبق البوصلة مباشرة.','اللؤلؤ ليس في أول رصيف ولا آخره.','التوابل تأتي بعد اللؤلؤ؛ الترتيب الوحيد: البلور، البوصلة، اللؤلؤ، التوابل.'],outro:'أظهر سجل الحمولة أن ساعة المد هي التي تفتح الطريق البحري إلى قصر المرايا.'},
 {id:'ml10_17',name:'ساعة المدّ',place:'برج المد والجزر',kind:'توقيت واستجابة متتابعة',scene:'17-tide-clock.webp',prop:'treasure/art/story5/ch5_s2_piece_gear_large.webp',objective:'أوقف مؤشر الساعة عند ثلاث نوافذ آمنة بالترتيب. استنتج مواضعها من القرائن ثم نفّذ التوقيت قبل عودة الموجة.',story:'تتحكم ساعة المدّ في بوابة الميناء. يدور المؤشر حول ثمانية قطاعات، ولا تثبت البوابة إلا إذا أُوقفت الموجة في ثلاث لحظات متتابعة.',moods:['happy','thinking','curious'],talk:['سأحسب مواضع النوافذ أولاً، ثم أوقف المؤشر عند مرورها.','لا تضغطي بسرعة؛ انتظري اقتراب القطاع الصحيح.','الموجة تتسارع… سأراقب المؤشر والوقت معاً.'],hint:['النافذة الأولى تبعد قطاعين مع عقارب الساعة عن علامة الشمال.','الثانية تبعد ثلاثة قطاعات عن الأولى.','الثالثة تبعد أربعة قطاعات عن الثانية؛ الترتيب ٣، ٦، ٢ عند العدّ من الصفر.'],outro:'استقرت ساعة المد، وظهر مدخل إلى رواق المرايا القديمة.'},
 {id:'ml10_18',name:'رقع رواق المرايا',place:'رواق المرايا المكسور',kind:'تركيب مكاني وتسلسل حركات',scene:'18-mask-gallery.webp',prop:'treasure/art/story5/ch1_s3_piece_mirror.webp',objective:'حرّك الرقع المجاورة للفراغ لإعادة صورة ختم المرايا. أمامك ثماني حركات، والمسار الأقصر الوحيد يعيد النقش كاملاً.',story:'في الرواق، تحوّل ختم القبطان إلى تسع رقع حجرية. لا يمكن نقل رقعة عبر أخرى؛ حرّك الرقعة الملامسة للفراغ حتى يعود النقش إلى ترتيبه.',moods:['curious','thinking','alert'],talk:['سأبحث عن حركة تفتح الطريق للرقع التالية، لا عن خطوة تبدو صحيحة الآن فقط.','الفراغ هو المساحة الوحيدة التي تسمح بتبديل موضع القطعة.','ثماني حركات فقط؛ لنبدأ بالقطعة التي تفتح العمود الأيسر.'],hint:['الفراغ يبدأ في الركن السفلي الأيمن؛ انقلي الرقعة المجاورة إليه، لا تحاولي سحب الرقعة عبر غيرها.','أول رقعتين تتحركان من العمود الأيمن إلى أسفل، ثم تنتقل الرقعتان العلويتان إلى اليمين.','مسار الفراغ الأقصر: أعلى، أعلى، يسار، يسار، أسفل، أسفل، يمين، يمين؛ أي أن الرقع تتحرك عكس اتجاه الفراغ.'],outro:'عاد ختم المرايا إلى صورته، وكشف مخزناً لا يفتح إلا بتحريك صندوق القبطان.'},
 {id:'ml10_19',name:'صندوق القبطان',place:'مخزن الرياح والبضائع',kind:'تخطيط دفع وتحريك مكاني',scene:'19-wind-lab.webp',prop:'watercolor/art/icons54/chest.webp',objective:'ادفع الصندوق إلى منصة الختم. تستطيع المشي في الممرات المفتوحة، لكن الصندوق لا يتحرك إلا إذا وقفت خلفه. الحل يحتاج ست دفعات بالضبط.',story:'أخفى القبطان مفتاح الرواق داخل صندوق ثقيل. لا يمكن سحبه؛ يجب دفعه عبر الممر الحجري حتى يصل إلى منصة الختم.',moods:['thinking','alert','curious'],talk:['سأفحص الممرات قبل دفع الصندوق؛ قد أحاصر نفسي إن استعجلت.','يمكنني المشي حول الصندوق، لكن لا أستطيع سحبه إلى الخلف.','ست دفعات تكفي إن حافظنا على مسار الصندوق.'],hint:['ابدئي من خلف الصندوق عند أسفل الممر وادفعيه إلى الأعلى.','استمري في دفعه شمالاً أربع خلايا حتى يصل إلى الممر العلوي.','بعد ذلك التفّي من الممر الجانبي وادفعيه يميناً مرتين.'],outro:'وصل الصندوق إلى منصة الختم، وفتح قاعة اختبار حارس المرايا.'},
 {id:'ml10_20',name:'اختبار حارس المرايا',place:'بوابة قصر المرايا',kind:'تخطيط قفزات الفارس',scene:'20-guardian-gate.webp',prop:'treasure/art/story5/ch7_seal_dawn.webp',objective:'حرّك قطعة الفارس بقفزات الشطرنج، واجمع الأختام الثلاثة بالترتيب قبل الوصول إلى البوابة. لديك ثماني قفزات فقط.',story:'وقف حارس المرايا أمام البوابة الأخيرة. لا يفتحها مفتاح أو قوة؛ يجب أن تعبر قطعة الفارس المسار الحجري، وتلمس الأختام الثلاثة بالترتيب الذي تركه القبطان.',moods:['thinking','alert','happy'],talk:['الفارس لا يتحرك بخط مستقيم؛ كل قفزة لها شكل محدد.','سأجمع الأختام بالترتيب، وأتجنب المربعات التي ابتلعها الحارس.','هذه آخر خطوة قبل قصر المرايا؛ لن أضيّع قفزة واحدة.'],hint:['الفارس يقفز مربعين في اتجاه وواحداً جانبياً؛ المربعات الداكنة مغلقة.','الأختام تظهر في المربعات المضيئة: الأول ثم الثاني ثم الثالث.','المسار الوحيد من ثماني قفزات هو المسار المضيء المتعرج من البداية إلى البوابة.'],outro:'اجتمعت الأختام الثلاثة وفتحت بوابة قصر المرايا، وكشفت ممراً سرياً إلى حديقة الفوانيس وأحواض المعبد.'},
 {id:'ml10_21',name:'متاهة الفوانيس',place:'حديقة الأضواء القديمة',kind:'تخطيط مسار في متاهة',scene:'21-lantern-maze.webp',prop:'watercolor/art/icons54/lantern.webp',objective:'اعبر ممرات الحديقة من بوابة البداية إلى بوابة الخروج. بعض الممرات تقود إلى جيوب مغلقة؛ استخدم التراجع عندما تكتشف طريقاً مسدوداً.',story:'خلف بوابة قصر المرايا امتدت حديقة قديمة، وفوانيسها تضيء ممرات ملتوية. وضعت ورد علامة عند المخرج، لكن الممرات الجانبية قد تخدع من يندفع دون قراءة الطريق.',moods:['thinking','curious','alert'],talk:['سأرسم المسار في ذهني وأتأكد من كل منعطف قبل أن أتابع.','أرى أن بعض الفوانيس تضيء طريقاً قصيراً لكنه ينتهي بجدار.','سأبقي عيناً على نقطة البداية حتى أستطيع الرجوع إن لزم.'],hint:['ابدأ من الركن السفلي الأيسر واتبع الممر الصاعد أولاً.','بعد الوصول إلى الممر الأوسط، انعطف يميناً ثم اصعد إلى الممر العلوي.','المسار الوحيد يمر عبر ١٣ خانة: أعلى، أعلى، يمين، يمين، أعلى، أعلى، يمين، يمين، أعلى، أعلى، يمين، يمين.'],outro:'وصلت البطلات إلى نهاية الحديقة، وهناك وجدن أحواضاً حجرية لا تعمل إلا بقياس الماء بدقة.'},
 {id:'ml10_22',name:'أحواض المعبد',place:'صهريج المياه الحجري',kind:'استدلال كمي ونقل السوائل',scene:'22-waterworks.webp',prop:'watercolor/art/icons54/wheel.webp',objective:'لديك حوض كبير سعته ٧ وحدات وحوض صغير سعته ٤ وحدات. استخدم التعبئة والإفراغ والسكب حتى يصبح في الحوض الكبير ٥ وحدات بالضبط.',story:'توقفت عجلة المعبد لأن الصهريج يحتاج إلى خمس وحدات ماء بالضبط. لا توجد علامات قياس؛ عليك الاعتماد على سعات الحوضين وعمليات النقل بينهما.',moods:['thinking','curious','alert'],talk:['سنستخدم اختلاف السعتين لصناعة كمية لا يمكن قياسها مباشرة.','راقب ما يتبقى في الحوض بعد أن يمتلئ الآخر؛ الباقي هو الدليل.','لا تفرغ الماء عشوائياً؛ لكل عملية مكانها في التسلسل.'],hint:['الحوضان فارغان في البداية؛ ابدأ بملء الحوض الصغير.','اسكب محتواه في الكبير، ثم كرر الملء والسكب حتى يبقى مقدار صغير في الحوض الثاني.','التسلسل الأقصر الوحيد ثماني عمليات: ملء الصغير، سكب في الكبير، ملء الصغير، سكب، إفراغ الكبير، سكب الباقي، ملء الصغير، ثم سكب أخير.'],outro:'استقرت المياه عند العلامة الخامسة، فدارت العجلة واشتعلت أبراج الإشارة حول الخليج.'},
 {id:'ml10_23',name:'أبراج الإشارة',place:'خليج المنارات الخمس',kind:'منطق تبديل الحالات',scene:'23-signal-towers.webp',prop:'watercolor/art/icons54/bell.webp',objective:'أطفئ جميع إشارات الأبراج. كل ضغطة تبدّل حالة البرج نفسه والأبراج المتصلة به من الشمال والجنوب والشرق والغرب. استخدم أربع ضغطات فقط.',story:'تتواصل الأبراج بنبضات ضوئية؛ الضغط على برج يبدل إشارته وإشارات جيرانه المباشرين. يجب إطفاء الشبكة كلها بأربع ضغطات دقيقة، لا أكثر ولا أقل.',moods:['curious','thinking','happy'],talk:['كل برج يؤثر في جيرانه؛ لا تفكر في كل ضوء بمعزل عن الشبكة.','إذا ضغطنا على برج مرتين نلغي أثر الضغط الأول، لذا نحتاج خطة محسوبة.','سأتابع الصفوف والأعمدة معاً حتى لا نعيد تشغيل برج أطفأناه.'],hint:['ابدأ بالنظر إلى زوايا الشبكة؛ البرج الركني يؤثر في خانتين فقط بجانبه إضافة إلى نفسه.','الضغط على برج يبدل نفسه وأقرب جار أفقي أو رأسي، ولا يؤثر قطرياً.','مجموعة الضغط الوحيدة: أعلى اليسار، أعلى اليمين، الوسط، أسفل اليسار.'],outro:'انطفأت الإشارات بعد أربع ضغطات، واجتمع ضوء الأبراج ليكشف غرفة الأقراص الثلاثة.'},
 {id:'ml10_24',name:'أقراص الحارس',place:'قاعة الأقراص الثلاثة',kind:'تخطيط تسلسلي وقواعد نقل',scene:'24-disk-temple.webp',prop:'watercolor/art/icons54/gear.webp',objective:'انقل الأقراص الثلاثة من العمود الأول إلى العمود الثالث. لا تضع قرصاً كبيراً فوق قرص أصغر، وانقل قرصاً واحداً فقط في كل حركة. أكمل في سبع حركات.',story:'تغلق الأقراص الحجرية طريق الختم. لا تتحرك إلا إذا حافظت على ترتيب أحجامها؛ القرص الأصغر وحده يمكن أن يستقر فوق الأكبر.',moods:['thinking','alert','curious'],talk:['علينا نقل الأصغر أولاً، لكن ليس كل نقل يفتح الخطوة التالية.','سأستخدم العمود الأوسط مؤقتاً كي أحرر القرص الأكبر.','سبع حركات تكفي تماماً؛ أي حركة زائدة تعني أن الخطة تحتاج إلى إعادة.'],hint:['لا تحرك إلا القرص الظاهر أعلى العمود؛ الأقراص تحته لا يمكن الوصول إليها.','لا تضع قرصاً أكبر فوق قرص أصغر. استخدم العمود الأوسط لحفظ قرص مؤقتاً.','الحل الأقصر الوحيد سبع نقلات: ١ إلى ٣، ١ إلى ٢، ٣ إلى ٢، ١ إلى ٣، ٢ إلى ١، ٢ إلى ٣، ١ إلى ٣.'],outro:'استقرت الأقراص الثلاثة في العمود الأخير، وانفتح مدخل الختم الخماسي في قلب المعبد.'},
 {id:'ml10_25',name:'الختم الخماسي',place:'محراب أَثْران الأخير',kind:'استنتاج ترتيبي متعدد القيود',scene:'25-fivefold-seal.webp',prop:'watercolor/art/icons54/lock.webp',objective:'رتّب الرموز الخمسة على الختم وفق أربع قرائن مترابطة. لكل رمز موضع واحد، ولا يفتح المحراب إلا بالترتيب الكامل الصحيح.',story:'وصلت رواء ونهى وورد إلى محراب أَثْران. أمامهن خمسة رموز جمعتها الرحلة: القمر والورقة والماء والنجمة والنار. النقوش لا تعطي مواضع مباشرة، بل علاقات يجب جمعها في ترتيب واحد.',moods:['thinking','curious','alert'],talk:['سأحوّل كل قرينة إلى علاقة بين موضعين، ثم أرتب السلسلة كاملة.','لن تعمل الأقراص إذا تكرر رمز أو بقي موضع فارغ.','هذا هو الختم الأخير؛ لا نحتاج إلى تخمين، فالقرائن تكفي وحدها.'],hint:['القمر يسبق الورقة مباشرة؛ ضعهما متجاورين بهذا الترتيب.','الورقة تأتي قبل الماء، والنجمة تأتي بعد الماء.','النار في الموضع الأخير؛ الترتيب الوحيد: القمر، الورقة، الماء، النجمة، النار.'],outro:'اكتمل الختم الخماسي، واشتعل قلب أَثْران. انفتحت بوابة قصر المرايا، وظهر الطريق إلى الفصل الثاني. انتهى الفصل الافتتاحي بخمس وعشرين محطة.'}
 ];
