const itemNames={map:'الخريطة',compass:'البوصلة',lantern:'الفانوس',telescope:'المنظار',key:'المفتاح',moon:'القمر',anchor:'المرساة',sun:'الشمس'};
const scenePaths=st=>SC+st.scene;
function artDetailsHtml(st,mode='game'){return `<div class="ex10-art-details ${mode}" aria-label="عناصر مرسومة خاصة باللغز">${(st.artDetails||[]).map(item=>`<span class="ex10-art-detail"><img src="${item.src}" alt="${item.label}" loading="lazy" decoding="async"><small>${item.label}</small></span>`).join('')}</div>`;}
let view='hub',active=-1,timerId=null,previewTimer=null,timerLeft=0,gameState=null,root=$('#v-puz'),baseRender=null,charMoods=[],lastStoryBeat=null;
function emptySave(){return{done:{},stars:{},best:{},totalStars:0,updated:0};}
function loadSave(){try{const x=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(!x||typeof x!=='object')return emptySave();return{...emptySave(),...x,done:x.done||{},stars:x.stars||{},best:x.best||{}};}catch(e){return emptySave();}}
let save=loadSave();function saveNow(){save.updated=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));}catch(e){}}
function completed(){return stages.filter(s=>save.done[s.id]).length;}
function unlocked(i){return i===0||!!save.done[stages[i-1].id];}
function stopTimer(){if(timerId){clearInterval(timerId);timerId=null;}if(previewTimer){clearTimeout(previewTimer);previewTimer=null;}}
function ar(n){return String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[+d]);}
function heroImages(){return[
 {key:'roaa',name:'رواء',role:'قائدة الطاقم',src:CREW+'roaa.webp'},
 {key:'noha',name:'نهى',role:'مهندسة الآلات',src:CREW+'noha.webp'},
 {key:'ward',name:'ورد',role:'قارئة الأدلة',src:CREW+'ward.webp'}];}
function poseForMood(mood){if(mood==='thinking')return'thinking';if(mood==='worried'||mood==='alert')return'worried';if(mood==='curious')return'curious';if(mood==='happy'||mood==='celebrate')return'happy';return'welcome';}
function heroPoseSrc(key,mood){return CREW+'poses/'+key+'-'+poseForMood(mood)+'.webp';}
function crewHtml(i,mini=false,override){const st=stages[i],moods=override||st.moods;return `<div class="${mini?'ex10-crew-mini':'ex10-crew'}" aria-label="الشخصيات الرئيسية">${heroImages().map((c,k)=>{const mood=moods[k]||'thinking',src=heroPoseSrc(c.key,mood);return `<article class="ex10-heroine" data-character="${c.key}" data-mood="${mood}" data-action="${poseForMood(mood)}"><img src="${src}" data-pose-src="${src}" data-fallback-src="${c.src}" alt="${c.name} — ${c.role}" loading="eager" decoding="async"><div><b>${c.name}</b><small>${c.role}</small></div></article>`;}).join('')}</div>`;}
function setHeroinePose(el,mood){const img=$('img',el),src=heroPoseSrc(el.dataset.character,mood),changed=el.dataset.mood!==mood;el.dataset.mood=mood;el.dataset.action=poseForMood(mood);if(changed){el.classList.remove('pose-react');void el.offsetWidth;el.classList.add('pose-react');}if(!img||img.dataset.poseSrc===src)return;img.classList.add('pose-switching');img.addEventListener('load',()=>img.classList.remove('pose-switching'),{once:true});img.addEventListener('error',()=>{img.onerror=null;img.classList.remove('pose-switching');img.src=img.dataset.fallbackSrc;},{once:true});img.src=src;img.dataset.poseSrc=src;}
function preloadCrewPoses(){heroImages().forEach(c=>['welcome','thinking','worried','curious','happy'].forEach(p=>{const im=new Image();im.decoding='async';im.src=CREW+'poses/'+c.key+'-'+p+'.webp';}));}
function header(){return `<header class="ex10-header"><div class="ex10-brand"><span class="ex10-compass">✥</span><div><h1>مختبر العقل</h1><small>رحلة جانبية في أرض أَثْران</small></div></div><div class="ex10-stats"><span class="ex10-stat">★ ${ar(save.totalStars)} / ٧٥</span><span class="ex10-stat">✦ ${ar(completed())} / ٢٥</span></div></header>`;}
function mapPositions(){/* 5.5.28: nudged (≤6 points) so no two stations overlap and none is clipped from 320px phones to tablets */return[[21,64],[34,49],[48,57],[63,36],[77,32],[79,54],[63,72],[83,77],[46,78],[51,14],[67,13],[91,30],[93,56],[69,86],[25,87],[7,70],[7,40],[31,8],[93,88],[93,8],[82,19],[63,25],[56,46],[42,33],[24,26]];}
function renderMap(){view='map';stopTimer();const positions=mapPositions(),done=completed();root.innerHTML=`<main class="ex10">${header()}<div class="ex10-panel"><div class="ex10-map-intro"><div><span class="ex10-eyebrow">رحلة جانبية · خمس وعشرون مرحلة قابلة للعب</span><h2 class="ex10-title">أرض أَثْران: سرّ القلب المفقود</h2><p class="ex10-sub">اجمعوا العلامات الخمس والعشرين، وافتحوا حديقة الفوانيس وأحواض المعبد وأبراج الإشارة وغرفة الأقراص والختم الأخير.</p></div><button class="ex10-back" data-ex10="hub">رجوع إلى المكتبة ↶</button></div><div class="ex10-map" role="group" aria-label="خريطة أرض أَثْران"><svg class="ex10-map-route" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="${positions.map(([x,y],k)=>(k?'L':'M')+x+' '+y).join(' ')}"/></svg>${stages.map((s,i)=>{const [x,y]=positions[i],d=!!save.done[s.id],u=unlocked(i),cls=d?'done':u?'current':'locked';return `<button class="ex10-node ${cls}" data-ex10-node="${i}" style="left:${x}%;top:${y}%" aria-label="${s.name} ${u?'متاحة':'مقفلة'}">${d?STATE_ICON.done:u?ar(i+1):STATE_ICON.locked}<small>${s.name}</small></button>`}).join('')}</div><div class="ex10-map-legend">المسار يتابع من قصر المرايا إلى حديقة الفوانيس وأحواض المعبد ثم محراب الختم الخماسي · المراحل تفتح بالتتابع</div><div class="ex10-map-footer"><span>التقدم: <b>${ar(done)} من ٢٥</b> مرحلة · النجوم ${ar(save.totalStars)} من ٧٥</span><button class="ex10-btn dark" data-ex10="continue">${done? 'تابع من آخر مرحلة':'ابدأ المغامرة'}</button></div></div><div class="ex10-section-head"><h3>محطات الرحلة</h3><small>كل محطة تتطلب حل لغزها لفتح التالية</small></div><section class="ex10-levels">${stages.map((s,i)=>{const d=!!save.done[s.id],u=unlocked(i),stars=save.stars[s.id]||0;return `<button class="ex10-level-card ${u?'':'locked'} ${d?'done':''}" data-ex10-node="${i}" ${u?'':'aria-disabled="true"'}><span class="ex10-level-thumb"><img src="${scenePaths(s)}" alt="" loading="lazy">${stateBadge(d?'done':u?'open':'locked')}</span><span><b>${ar(i+1)} · ${s.name}</b><small>${s.kind} · ${u?(d?'مكتملة ويمكن إعادتها':'متاحة للعب'):'تُفتح بعد المرحلة السابقة'}</small><span class="ex10-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</span></span></button>`}).join('')}</section><div class="ex10-section-head"><h3>ما وراء الرحلة</h3><small>العوالم التالية ظاهرة على الخريطة لكنها غير قابلة للعب في هذه النسخة</small></div><section class="ex10-future"><article><b>قصر المرايا</b><small>الفصل الثاني · يفتح بعد إتمام الختم الخماسي في المرحلة ٢٥</small></article><article><b>سواحل القراصنة</b><small>الفصل الثالث · مقفل</small></article><article><b>الحطام والمعبد</b><small>فصول لاحقة · مقفلة</small></article></section></main>`;
 root.querySelectorAll('[data-ex10-node]').forEach(b=>b.addEventListener('click',()=>{const i=+b.dataset.ex10Node;if(unlocked(i))renderIntro(i);else toast('أكمل المرحلة السابقة أولاً.');}));root.querySelector('[data-ex10="hub"]').onclick=()=>backHub();root.querySelector('[data-ex10="continue"]').onclick=()=>{const i=stages.findIndex(s=>!save.done[s.id]);renderIntro(i<0?24:i);};}
function toast(t){let n=root.querySelector('.ex10-toast');if(!n){n=document.createElement('div');n.className='ex10-toast';root.append(n);}n.textContent=t;}
function backHub(){stopTimer();view='hub';try{if(typeof baseRender==='function')baseRender();else renderPuz();}catch(e){}insertLaunch();}
function insertLaunch(){const v=$('#v-puz');if(!v||!v.querySelector('.v5-hublib')||v.querySelector('.ex10-launch'))return;const card=document.createElement('section');card.className='ex10-launch';card.innerHTML=`<div><span class="ex10-eyebrow" style="color:#f3d18a">رحلة جانبية · ٢٥ لغزاً جاهزة للعب</span><h2>رحلة أسرار أَثْران</h2><p>عالم مرسوم يدوياً، أدوات ومقتنيات مخصصة لكل لغز، ورواء ونهى وورد يتحركن ويتفاعلن مع أحداث الرحلة.</p></div><button class="ex10-launch-go" type="button">افتح الخريطة ←</button>`;card.querySelector('button').onclick=renderMap;const before=v.querySelector('.pzstory')||v.children[1]||null;v.insertBefore(card,before);}
function renderIntro(i){stopTimer();active=i;view='intro';const s=stages[i],beat=lastStoryBeat&&lastStoryBeat.nextIndex===i?`<aside class="ex10-story-transition" aria-live="polite"><span>انتقال في الرحلة</span><b>${lastStoryBeat.from} ← ${s.name}</b><p>${lastStoryBeat.text}</p></aside>`:'';lastStoryBeat=null;root.innerHTML=`<main class="ex10">${header()}<button class="ex10-back" data-ex10="map">← العودة إلى الخريطة</button>${beat}<section class="ex10-panel"><div class="ex10-stage-hero"><img src="${scenePaths(s)}" alt="مشهد ${s.place}"><img class="ex10-stage-prop" src="${s.prop}" alt="${s.name} — عنصر مرسوم خاص" loading="eager"><div class="ex10-stage-hero-copy"><span class="ex10-eyebrow" style="color:#f9d98b">المرحلة ${ar(i+1)} · ${s.place}</span><h2>${s.name}</h2><p>${s.objective}</p></div></div><div class="ex10-brief"><span class="ex10-eyebrow">مقدمة الرحلة</span><p style="margin:4px 0 10px;line-height:1.8;color:#684c2c;font-size:13px">${s.story}</p>${artDetailsHtml(s,'intro')} ${crewHtml(i)}<div class="ex10-dialogue" aria-live="polite"><strong>${i%3===0?'رواء':i%3===1?'نهى':'ورد'}:</strong> ${s.talk[i%3]}</div><div class="ex10-start-row"><small>نوع التحدي: ${s.kind} · ${i===6?'مؤقت ٤٥ ثانية':i===11?'حد أقصى ٧ انزلاقات':i===16?'مؤقت ٣٥ ثانية':i===17?'حد أقصى ٨ حركات':i===18?'حد أقصى ٦ دفعات':i===19?'حد أقصى ٨ قفزات':i===20?'مسار فريد من ١٢ خطوة':i===21?'٨ عمليات قياس':i===22?'٤ ضغطات دقيقة':i===23?'٧ نقلات قانونية':i===24?'٥ رموز · ترتيب وحيد':'لا يوجد وقت إجباري'}</small><button class="ex10-btn" data-ex10="start">ابدأ التحدي</button></div></div></section></main>`;
 root.querySelector('[data-ex10="map"]').onclick=renderMap;root.querySelector('[data-ex10="start"]').onclick=()=>startStage(i);}
const STATE_ICON={locked:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10.5" width="14" height="10" rx="2.2" fill="currentColor"/><path d="M8 10.5V8a4 4 0 0 1 8 0v2.5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/><circle cx="12" cy="15.5" r="1.6" fill="#1b2c33"/></svg>',open:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10.5" width="14" height="10" rx="2.2" fill="currentColor"/><path d="M8 10.5V8a4 4 0 0 1 7.6-1.7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>',done:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.2 4.2L19 7" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'};
const STATE_LABEL={locked:'مقفلة',open:'مفتوحة',done:'مكتملة'};
function stateBadge(st){return `<i class="ex10-state-badge ${st}" role="img" aria-label="${STATE_LABEL[st]}">${STATE_ICON[st]}</i>`;}
function commonGame(i,inner,extra=''){const s=stages[i],progress=Math.round(((i+1)/stages.length)*100);return `<main class="ex10">${header()}<div class="ex10-game-shell"><div class="ex10-game-top"><div><b>${ar(i+1)} · ${s.name}</b><br><small>${s.place} · ${s.kind}</small></div><div class="ex10-top-right">${extra}<button class="ex10-back" data-ex10="map">الخريطة ×</button></div></div><div class="ex10-stage-progress" role="progressbar" aria-label="تقدم الرحلة" aria-valuemin="1" aria-valuemax="25" aria-valuenow="${i+1}"><div><span>المحطة ${ar(i+1)} من ${ar(stages.length)}</span><b>${ar(completed())} مكتملة</b></div><i style="width:${progress}%"></i></div><div class="ex10-game-scene ex10-scene-enter" data-state="${save.done[s.id]?'done':'locked'}" style="background-image:url('${scenePaths(s)}')"><span>${s.place}</span>${stateBadge(save.done[s.id]?'done':'locked')}</div><div class="ex10-game-content"><section class="ex10-brief" aria-label="بطاقة المحطة"><div class="ex10-stage-prop-inline"><img src="${s.prop}" alt="عنصر مرسوم خاص بـ ${s.name}" loading="lazy" decoding="async"><p class="ex10-objective">${s.objective}</p></div>${artDetailsHtml(s)}<div class="ex10-brief-crew">${crewHtml(i,true)}<div class="ex10-dialogue ex10-live-dialogue" aria-live="polite"><strong>${['رواء','نهى','ورد'][i%3]}:</strong> ${s.talk[i%3]}</div></div></section>${inner}<div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="hint">تلميح</button><button class="ex10-btn secondary" data-ex10="restart">إعادة المرحلة</button><button class="ex10-btn dark" data-ex10="map2">الخريطة</button></div><div class="ex10-feedback" id="ex10-feedback" role="status" aria-live="polite" aria-atomic="true">ابدأ بالتفكير، ثم نفّذ حركتك.</div><div id="ex10-hint" class="ex10-hint" role="note" hidden></div></div></div></main>`;}
function bindCommon(i){root.querySelector('[data-ex10="map"]').onclick=renderMap;root.querySelector('[data-ex10="map2"]').onclick=renderMap;root.querySelector('[data-ex10="restart"]').onclick=()=>startStage(i);root.querySelector('[data-ex10="hint"]').onclick=()=>showHint(i);}
function feedback(text,kind=''){const b=$('#ex10-feedback',root);if(b){b.textContent=text;b.className='ex10-feedback'+(kind?' '+kind:'');}if(kind==='bad')updateCrew(['worried','thinking','curious'],['نهى','توقف لحظة، لنعيد فحص الدليل قبل الخطوة التالية.']);else if(kind==='good')updateCrew(['thinking','happy','curious'],['رواء','هذه خطوة صحيحة؛ واصل بناء الحل.']);}
function updateCrew(moods,words){const crew=root.querySelector('.ex10-crew-mini, .ex10-crew');if(!crew)return;const imgs=$$('.ex10-heroine',crew);imgs.forEach((el,k)=>{if(moods&&moods[k])setHeroinePose(el,moods[k]);});if(words){let d=root.querySelector('.ex10-dialogue');if(!d){d=document.createElement('div');d.className='ex10-dialogue';crew.after(d);}d.innerHTML=`<strong>${words[0]}:</strong> ${words[1]}`;}}
function showHint(i){const s=stages[i],n=(gameState.hints||0);gameState.hints=n+1;const h=$('#ex10-hint',root);if(h){h.hidden=false;h.textContent=s.hint[Math.min(n,s.hint.length-1)];}feedback('ظهر تلميح جديد؛ سيؤثر على نجوم الإتقان فقط.','');updateCrew(['thinking','curious','curious'],['ورد','وجدت ملاحظة قد تساعدنا، لكن القرار لك.']);}
function winStage(i,message){stopTimer();if(!gameState||gameState.finished)return;gameState.finished=true;{const sc=root.querySelector('.ex10-game-scene');if(sc){sc.dataset.state='done';const b=sc.querySelector('.ex10-state-badge');if(b)b.outerHTML=stateBadge('done');}}const id=stages[i].id,stars=gameState.hints?1:gameState.errors?2:3;save.done[id]=true;save.stars[id]=Math.max(save.stars[id]||0,stars);save.best[id]=Math.max(save.best[id]||0,stars);save.totalStars=Object.values(save.stars).reduce((a,b)=>a+b,0);saveNow();lastStoryBeat={from:stages[i].name,text:stages[i].outro,nextIndex:i+1};renderOutcome(i,true,message,stars);}
function failStage(i,message){stopTimer();if(!gameState||gameState.finished)return;gameState.finished=true;renderOutcome(i,false,message,0);}
function renderOutcome(i,success,message,stars){const s=stages[i];root.innerHTML=`<main class="ex10">${header()}<section class="ex10-outcome"><div class="emblem">${success?'🏆':'🧭'}</div><span class="ex10-eyebrow">${success?'تم فتح المحطة التالية':'لم تكتمل المحاولة'}</span><h2>${success?'نجاح!':'تعثر مؤقت'}</h2><p>${message||s.outro}</p>${success?`<aside class="ex10-outcome-story"><span>ما الذي تغيّر في الرحلة؟</span><p>${s.outro}</p></aside><div class="ex10-stars-big">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>حصلت على ${ar(stars)} نجوم. ${stars===3?'إتقان كامل دون أخطاء أو تلميحات.':stars===2?'حل صحيح مع بعض الأخطاء.':'تم الحل بعد استخدام التلميح.'}</p>`:`<p>لم نحذف تقدمك السابق. يمكنك إعادة المحاولة أو العودة إلى الخريطة.</p>`}${crewHtml(i,false,success?['happy','happy','happy']:['thinking','worried','curious'])}<div class="ex10-actions-row">${success&&i<24?`<button class="ex10-btn" data-ex10="next">المرحلة التالية ←</button>`:''}${success&&i===24?`<button class="ex10-btn" data-ex10="epilogue">شاهد خاتمة الرحلة</button>`:''}<button class="ex10-btn secondary" data-ex10="retry">${success?'إعادة اللعب':'حاول مرة أخرى'}</button><button class="ex10-btn dark" data-ex10="map">الخريطة</button></div></section></main>`;
 const next=root.querySelector('[data-ex10="next"]');if(next)next.onclick=()=>renderIntro(i+1);const ep=root.querySelector('[data-ex10="epilogue"]');if(ep)ep.onclick=renderEpilogue;root.querySelector('[data-ex10="retry"]').onclick=()=>renderIntro(i);root.querySelector('[data-ex10="map"]').onclick=renderMap;}
function renderEpilogue(){root.innerHTML=`<main class="ex10">${header()}<section class="ex10-outcome"><div class="emblem">🌊</div><span class="ex10-eyebrow">نهاية الرحلة</span><h2>عاد قلب أَثْران إلى النبض</h2><p>اجتمعت العلامات الخمس والعشرون، واستعادت البطلات ختم أَثْران الخماسي. انفتحت بوابة قصر المرايا وظهر الطريق إلى الفصل الثاني، الذي سيبقى مقفلاً حتى يبدأ تطويره.</p>${crewHtml(24)}<div class="ex10-actions-row"><button class="ex10-btn" data-ex10="map">استكشف الخريطة</button></div></section></main>`;root.querySelector('[data-ex10="map"]').onclick=renderMap;}
function startStage(i){stopTimer();active=i;view='game';gameState={hints:0,errors:0,moves:0,finished:false};switch(i){case 0:gameCode(i);break;case 1:gameRiver(i);break;case 2:gameMap(i);break;case 3:gameBalance(i);break;case 4:gameMemory(i);break;case 5:gameMirrors(i);break;case 6:gameTimed(i);break;case 7:gameIslands(i);break;case 8:gameArchiveGrid(i);break;case 9:gameStars(i);break;case 10:gamePipes(i);break;case 11:gameIce(i);break;case 12:gameNim(i);break;case 13:gameShadows(i);break;case 14:gameCipher(i);break;case 15:gameManifest(i);break;case 16:gameTideClock(i);break;case 17:gameRelics(i);break;case 18:gameCrate(i);break;case 19:gameKnight(i);break;case 20:gameLanternMaze(i);break;case 21:gameWaterJugs(i);break;case 22:gameSignalTowers(i);break;case 23:gameHanoi(i);break;case 24:gameFivefoldSeal(i);break;}}
function gameCode(i){let digits=[0,0,0],tries=0;root.innerHTML=commonGame(i,`<div class="ex10-clues">${L.CODE_CLUES.map((c,k)=>`<div class="ex10-clue"><b>المحاولة ${ar(k+1)}</b><br>${c.guess.split('').join(' · ')}<br><small>${c.well?`صحيح وفي مكانه: ${ar(c.well)}`:'لا يوجد رقم في مكانه'} · ${c.wrong?`صحيح في مكان آخر: ${ar(c.wrong)}`:'لا رقم صحيح في مكان آخر'}</small></div>`).join('')}</div><div class="ex10-dials">${digits.map((d,k)=>`<div class="ex10-dial"><button data-dial="${k}" data-dir="up" aria-label="زيادة الرقم">▲</button><strong id="ex10-d${k}">٠</strong><button data-dial="${k}" data-dir="down" aria-label="إنقاص الرقم">▼</button><small>الخانة ${ar(k+1)}</small></div>`).join('')}</div><div class="ex10-controls"><button class="ex10-btn" data-ex10="check-code">جرّب الرمز</button><span class="ex10-stat">محاولات متبقية: <b id="ex10-attempts">٥</b></span></div>`);bindCommon(i);
 root.querySelectorAll('[data-dial]').forEach(b=>b.onclick=()=>{const k=+b.dataset.dial;digits[k]=(digits[k]+(b.dataset.dir==='up'?1:9))%10;$('#ex10-d'+k,root).textContent=ar(digits[k]);gameState.moves++;});
 root.querySelector('[data-ex10="check-code"]').onclick=()=>{tries++;gameState.moves++;if(digits.join('')===L.TARGET_CODE){winStage(i,'انفتح قفل المنارة، وعاد شعاعها ليضيء الممر البحري.');return;}gameState.errors++;$('#ex10-attempts',root).textContent=ar(5-tries);feedback('لم يفتح القفل. راجع عدد الأرقام الصحيحة ومواقعها.','bad');updateCrew(['thinking','worried','curious'],['نهى','القفل ما زال مغلقاً… لنراجع القرائن بهدوء.']);if(tries>=5)failStage(i,'نفدت محاولات القفل الخمس. لم نفقد تقدمك؛ أعد المحاولة بعد مراجعة الأدلة.');};}
function gameRiver(i){const nodes=[['P','المرسى',50,88,'⚓'],['A','النخلة',23,73,'🌴'],['B','الصخرة',23,48,'🪨'],['C','القوس',50,35,'🏛'],['D','البرج',77,48,'🗼'],['E','الرصيف',77,22,'🪵'],['F','الضفة',50,14,'🏝'],['G','المخرج',22,20,'🚩'],['X','شعاب',48,68,'✕'],['Y','دوامة',88,71,'✕'],['Z','صخور',35,8,'✕']];const edges=[['P','A'],['A','B'],['B','C'],['C','D'],['D','E'],['E','F'],['F','G'],['A','X'],['D','Y'],['F','Z']];gameState.path=['P'];const board=`<div class="ex10-graph" id="ex10-route"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${edges.map(([a,b])=>{const n=nodes.find(x=>x[0]===a),m=nodes.find(x=>x[0]===b);return `<line data-edge="${a}-${b}" x1="${n[2]}" y1="${n[3]}" x2="${m[2]}" y2="${m[3]}"/>`;}).join('')}</svg>${nodes.map(n=>`<button class="ex10-graph-node ${n[0]==='P'?'active':''} ${n[0]==='X'||n[0]==='Y'||n[0]==='Z'?'decoy':''}" data-route-node="${n[0]}" style="left:${n[2]}%;top:${n[3]}%" aria-label="${n[1]}">${n[4]}<small>${n[1]}</small></button>`).join('')}</div><p class="ex10-objective">اختر محطة مجاورة فقط. يمكنك العودة إلى العقدة السابقة للتراجع عن خطوة.</p><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-route">تراجع خطوة</button><button class="ex10-btn secondary" data-ex10="reset-route">إعادة المسار</button></div>`;root.innerHTML=commonGame(i,board);bindCommon(i);const graph=L.riverGraph;
 function paint(){const p=gameState.path;root.querySelectorAll('[data-route-node]').forEach(b=>{b.classList.toggle('visited',p.includes(b.dataset.routeNode));b.classList.toggle('active',b.dataset.routeNode===p[p.length-1]);});root.querySelectorAll('.ex10-graph line').forEach(line=>{const [a,b]=line.dataset.edge.split('-');line.classList.toggle('route-done',p.includes(a)&&p.includes(b)&&Math.abs(p.indexOf(a)-p.indexOf(b))===1);});}
 root.querySelectorAll('[data-route-node]').forEach(b=>b.onclick=()=>{const n=b.dataset.routeNode,p=gameState.path,last=p[p.length-1];if(p.length>1&&n===p[p.length-2]){p.pop();paint();return;}if((graph[last]||[]).includes(n)&&!p.includes(n)){p.push(n);gameState.moves++;paint();if(n==='G'){if(p.join('|')===L.audit().river.path.join('|'))winStage(i,'وصل القارب إلى الضفة عبر الممر الوحيد الآمن.');else{gameState.errors++;feedback('وصلت إلى المخرج لكن الترتيب لم يكن المسار المعتمد. أعد تتبع الممرات.','bad');}}else if(['X','Y','Z'].includes(n)){feedback('هذا الممر ينتهي عند صخور مغلقة. ارجع خطوة.','bad');gameState.errors++;}else feedback('خطوة صحيحة. استمر على امتداد النهر.','good');}else feedback('هذه المحطة غير متصلة بموضعك الحالي.','bad');});
 root.querySelector('[data-ex10="undo-route"]').onclick=()=>{if(gameState.path.length>1){gameState.path.pop();paint();}};root.querySelector('[data-ex10="reset-route"]').onclick=()=>{gameState.path=['P'];paint();};paint();}
function gameMap(i){gameState.pieces=[2,0,3,1];gameState.selected=-1;const labels=[['المنارة','watercolor/art/icons54/lantern.webp',['','A','B','']],['البوصلة','watercolor/art/icons54/compass.webp',['','','C','A']],['النهر','watercolor/art/icons54/bridge.webp',['B','D','','']],['المفتاح','watercolor/art/icons54/key.webp',['C','','','D']]];const names=['أعلى اليسار','أعلى اليمين','أسفل اليسار','أسفل اليمين'];const board=`<p class="ex10-objective">القطع الأربع تحمل وصلات مرمّزة. اجعل كل وصلة داخلية تتصل بنظيرتها، واجعل الحواف الفارغة على حدود اللوحة. اضغط قطعتين لتبديل مكانيهما.</p><div class="ex10-tiles" id="ex10-maptiles">${gameState.pieces.map((id,pos)=>{const p=labels[id];return tileHtml(id,pos,p,names[pos]);}).join('')}</div><div class="ex10-feedback" id="ex10-map-feedback">ابدأ بالقطعة التي لا تحمل وصلة عند حافتها العليا واليسرى.</div>`;root.innerHTML=commonGame(i,board);bindCommon(i);bindTiles();
 function tileHtml(id,pos,p,slot){return `<button class="ex10-tile" data-tile-pos="${pos}"><span class="edge n">${p[2][0]||'—'}</span><span class="edge e">${p[2][1]||'—'}</span><span class="edge s">${p[2][2]||'—'}</span><span class="edge w">${p[2][3]||'—'}</span><img src="${p[1]}" alt=""><b>${p[0]}</b><small style="display:block;text-align:center;color:#806542">${slot}</small></button>`;}
 function bindTiles(){root.querySelectorAll('[data-tile-pos]').forEach(b=>b.onclick=()=>{const pos=+b.dataset.tilePos;if(gameState.selected<0){gameState.selected=pos;b.classList.add('selected');return;}if(gameState.selected===pos){gameState.selected=-1;b.classList.remove('selected');return;}const a=gameState.selected;[gameState.pieces[a],gameState.pieces[pos]]=[gameState.pieces[pos],gameState.pieces[a]];gameState.moves++;gameState.selected=-1;root.querySelector('#ex10-maptiles').innerHTML=gameState.pieces.map((id,p)=>tileHtml(id,p,labels[id],names[p])).join('');bindTiles();if(gameState.pieces.join(',')==='0,1,2,3')winStage(i,'التأمت قطع الخريطة واتصلت خطوط الساحل الأربعة.');else feedback('وصلتان لا تتطابقان بعد. افحص الحواف الفارغة والرموز المتشابهة.');});}}
function gameBalance(i){gameState.heavy=7;gameState.weighings=0;gameState.pool=[0,1,2,3,4,5,6,7,8];gameState.left=[];gameState.right=[];gameState.first=null;gameState.second=null;gameState.guess=-1;
 const board=`<p class="ex10-objective">اختر ثلاث قطع في كل كفة للوزنة الأولى. بعد ظهور النتيجة، زن قطعتين من المجموعة المرشحة. بعدها حدّد القطعة الأثقل.</p><div class="ex10-scale-art" aria-hidden="true"><img class="ex10-scale-stand" src="treasure/art/story5/ch3_s2_piece_balance_stand.webp"><img class="ex10-scale-beam" src="treasure/art/story5/ch3_s2_piece_balance_beam.webp"><img class="ex10-scale-left" src="treasure/art/story5/ch3_s2_piece_balance_pan.webp"><img class="ex10-scale-right" src="treasure/art/story5/ch3_s2_piece_balance_pan.webp"></div><div class="ex10-weighing"><div class="ex10-pan"><b>الكفة اليسرى</b><span id="ex10-left">—</span><small id="ex10-lnum">٠ / ٣</small></div><div class="ex10-pan"><b>الكفة اليمنى</b><span id="ex10-right">—</span><small id="ex10-rnum">٠ / ٣</small></div></div><div class="ex10-coins">${Array.from({length:9},(_,n)=>`<button class="ex10-coin" data-coin="${n}">🪙 ${ar(n+1)}</button>`).join('')}</div><div class="ex10-controls"><button class="ex10-btn" data-ex10="weigh">زن الكفتين</button><button class="ex10-btn secondary" data-ex10="guess" disabled>تأكيد القطعة الأثقل</button></div><div class="ex10-clue" id="ex10-weigh-result">الوزنة الأولى: ثلاث قطع مقابل ثلاث قطع.</div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);updateWeighUI();root.querySelectorAll('[data-coin]').forEach(b=>b.onclick=()=>{const n=+b.dataset.coin,stage=gameState.weighings,allowed=stage===0?gameState.pool:gameState.pool;if(stage>=2){gameState.guess=n;root.querySelectorAll('[data-coin]').forEach(x=>x.classList.toggle('selected',+x.dataset.coin===n));return;}let left=gameState.left,right=gameState.right;if(left.includes(n)){left.splice(left.indexOf(n),1);}else if(right.includes(n)){right.splice(right.indexOf(n),1);}else{const required=stage===0?3:1;if(left.length<required)left.push(n);else if(right.length<required)right.push(n);else{feedback('اكتملت الكفتان؛ أزل قطعة قبل إضافة غيرها.','bad');return;}}root.querySelectorAll('[data-coin]').forEach(x=>x.classList.toggle('selected',left.includes(+x.dataset.coin)||right.includes(+x.dataset.coin)));updateWeighUI();});
 function updateWeighUI(){const left=gameState.left,right=gameState.right;$('#ex10-left',root).textContent=left.length?left.map(n=>ar(n+1)).join(' · '):'—';$('#ex10-right',root).textContent=right.length?right.map(n=>ar(n+1)).join(' · '):'—';$('#ex10-lnum',root).textContent=ar(left.length)+' / '+ar(gameState.weighings===0?3:1);$('#ex10-rnum',root).textContent=ar(right.length)+' / '+ar(gameState.weighings===0?3:1);root.querySelectorAll('[data-coin]').forEach(b=>{const n=+b.dataset.coin;b.disabled=gameState.weighings===1&&!gameState.pool.includes(n);b.classList.toggle('selected',left.includes(n)||right.includes(n));});}
 root.querySelector('[data-ex10="weigh"]').onclick=()=>{const n=gameState.weighings,need=n===0?3:1;if(gameState.left.length!==need||gameState.right.length!==need){feedback(`اختر ${ar(need)} في كل كفة أولاً.`,'bad');return;}if(gameState.left.some(x=>gameState.right.includes(x))){feedback('لا يمكن وضع القطعة نفسها في الكفتين.','bad');return;}const heavy=gameState.heavy,lv=gameState.left.some(x=>x===heavy),rv=gameState.right.some(x=>x===heavy),result=lv?'left':rv?'right':'equal';gameState.weighings++;gameState.moves++;if(n===0){gameState.first={left:gameState.left.slice(),right:gameState.right.slice(),result};gameState.pool=result==='left'?gameState.left.slice():result==='right'?gameState.right.slice():gameState.pool.filter(x=>!gameState.left.includes(x)&&!gameState.right.includes(x));$('#ex10-weigh-result',root).textContent=result==='equal'?'الوزنة الأولى متعادلة؛ القطعة الأثقل بين القطع الثلاث التي بقيت خارج الميزان.':result==='left'?'الوزنة الأولى: الكفة اليسرى أثقل؛ القطعة ضمن قطعها الثلاث.':'الوزنة الأولى: الكفة اليمنى أثقل؛ القطعة ضمن قطعها الثلاث.';gameState.left=[];gameState.right=[];root.querySelector('[data-ex10="weigh"]').textContent='نفّذ الوزنة الثانية';updateWeighUI();}else{gameState.second={left:gameState.left.slice(),right:gameState.right.slice(),result};const pair=[...gameState.left,...gameState.right],found=result==='left'?gameState.left[0]:result==='right'?gameState.right[0]:gameState.pool.find(x=>!pair.includes(x));gameState.found=found;$('#ex10-weigh-result',root).textContent='ظهرت نتيجة الوزنة الثانية. اختر القطعة التي يحددها الميزان.';root.querySelector('[data-ex10="weigh"]').disabled=true;root.querySelector('[data-ex10="weigh"]').textContent='اكتملت الوزنتان';root.querySelector('[data-ex10="guess"]').disabled=false;root.querySelector('[data-ex10="guess"]').textContent='تأكيد القطعة المختارة';$('#ex10-weigh-result',root).textContent=result==='equal'?'الوزنة الثانية متعادلة؛ القطعة الأثقل هي الثالثة التي لم توضع في الكفتين.':result==='left'?'الوزنة الثانية: الكفة اليسرى أثقل؛ القطعة المختارة من اليسار.':'الوزنة الثانية: الكفة اليمنى أثقل؛ القطعة المختارة من اليمين.';root.querySelectorAll('[data-coin]').forEach(b=>b.onclick=()=>{gameState.guess=+b.dataset.coin;root.querySelectorAll('[data-coin]').forEach(x=>x.classList.toggle('selected',+x.dataset.coin===gameState.guess));root.querySelector('[data-ex10="guess"]').textContent='تأكيد القطعة رقم '+ar(gameState.guess+1);});}};
 root.querySelector('[data-ex10="guess"]').onclick=()=>{if(gameState.guess<0){feedback('اختر القطعة التي تعتقد أنها الأثقل.','bad');return;}gameState.moves++;if(gameState.guess===gameState.found&&gameState.found===gameState.heavy)winStage(i,'حددت القطعة الأثقل باستخدام وزنتين فقط.');else{gameState.errors++;failStage(i,'لم تطابق القطعة التي اخترتها نتيجة الوزنتين. أعد المحاولة بخطة وزن مختلفة.');}};
}
function gameMemory(i){const seq=['⚓','🌙','✦','🐚','☀️'],symbols=['⚓','🌙','✦','🐚','☀️'];gameState.seq=seq;gameState.entered=[];gameState.previewing=true;
 const board=`<p class="ex10-objective">سيظهر تسلسل البلورات لمدة أربع ثوانٍ. احفظ الترتيب، ثم المس الرموز لإعادة التسلسل.</p><div id="ex10-preview" class="ex10-sequence"><span>…</span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="replay-memory">إعادة عرض التسلسل</button><button class="ex10-btn secondary" data-ex10="clear-memory">مسح الإجابة</button></div><div class="ex10-sequence" id="ex10-entered"></div><div class="ex10-runes">${symbols.map((s,k)=>`<button class="ex10-rune" data-rune="${k}" aria-label="الرمز ${ar(k+1)}">${s}</button>`).join('')}</div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);function preview(){if(previewTimer)clearTimeout(previewTimer);gameState.previewing=true;$('#ex10-preview',root).innerHTML=seq.map(s=>`<span>${s}</span>`).join('');feedback('احفظ التسلسل… سيختفي بعد أربع ثوانٍ.');root.querySelectorAll('[data-rune]').forEach(b=>b.disabled=true);previewTimer=setTimeout(()=>{previewTimer=null;if(view!=='game'||active!==i||gameState.finished)return;gameState.previewing=false;$('#ex10-preview',root).innerHTML='<span>؟</span><span>؟</span><span>؟</span><span>؟</span><span>؟</span>';root.querySelectorAll('[data-rune]').forEach(b=>b.disabled=false);feedback('أعد إدخال التسلسل من الذاكرة.');},4000);}function paint(){const box=$('#ex10-entered',root);box.innerHTML=gameState.entered.map(s=>`<span>${s}</span>`).join('')||'<small style="align-self:center;color:#806543">اختياراتك ستظهر هنا</small>';}
 root.querySelector('[data-ex10="replay-memory"]').onclick=()=>{preview();};root.querySelector('[data-ex10="clear-memory"]').onclick=()=>{gameState.entered=[];paint();};root.querySelectorAll('[data-rune]').forEach(b=>b.onclick=()=>{if(gameState.previewing||gameState.finished)return;const k=+b.dataset.rune;gameState.entered.push(symbols[k]);gameState.moves++;paint();if(gameState.entered.length===seq.length){if(gameState.entered.every((s,n)=>s===seq[n]))winStage(i,'أعدت تسلسل البلورات كاملاً من الذاكرة.');else{gameState.errors++;feedback('اختلط ترتيب الومضات. أعد العرض وحاول مجدداً.','bad');updateCrew(['curious','thinking','worried'],['ورد','لا بأس، أستطيع إعادة عرض الومضات متى شئت.']);gameState.entered=[];paint();}}});preview();}
function gameMirrors(i){const dirs=['شمال','شرق','جنوب','غرب'];gameState.orient=[0,0,0];const target=[1,3,2];const board=`<p class="ex10-objective">كل مرآة تدور ربع دورة مع كل ضغطة. طابق الاتجاهات المنقوشة لتصل حزمة الضوء إلى العدسة.</p><div class="ex10-mirrors">${['المرآة الأولى','المرآة الثانية','المرآة الثالثة'].map((n,k)=>`<div class="ex10-mirror"><button data-mirror="${k}" aria-label="تدوير ${n}">◩</button><b>${n}</b><small id="ex10-mdir${k}">شمال</small></div>`).join('')}</div><div class="ex10-clues"><div class="ex10-clue">الأولى تواجه شروق الشمس.</div><div class="ex10-clue">الثانية تواجه عكس اتجاه الأولى.</div><div class="ex10-clue">الثالثة ربع دورة مع عقارب الساعة من الأولى.</div></div>`;root.innerHTML=commonGame(i,board);bindCommon(i);root.querySelectorAll('[data-mirror]').forEach(b=>b.onclick=()=>{const k=+b.dataset.mirror;gameState.orient[k]=(gameState.orient[k]+1)%4;gameState.moves++;b.style.transform=`rotate(${gameState.orient[k]*90}deg)`;$('#ex10-mdir'+k,root).textContent=dirs[gameState.orient[k]];if(gameState.orient.every((x,n)=>x===target[n]))winStage(i,'انعكس الضوء عبر المرايا الثلاث ووصل إلى العدسة.');else feedback('تغيّر اتجاه الشعاع. تابع ضبط بقية المرايا.','good');});}
