const mxIcon=k=>`<svg viewBox="0 0 40 40" aria-hidden="true"><g fill="none" stroke="#3A2616" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">${MX_IC[k]||'<circle cx="20" cy="20" r="10"/>'}</g></svg>`;
const mxChip=(k,label,sm)=>`<span class="mk-chip${sm?' sm':''}">${mxIcon(k)}<small>${label}</small></span>`;
const mxRel=t=>`<span class="mk-rel ${t==='≠'||t==='ليس'?'ne':'seq'}">${t}</span>`;
const mxSlotMark=n=>`<span class="mk-chip sm"><svg viewBox="0 0 40 40"><rect x="8" y="10" width="24" height="20" rx="3" fill="none" stroke="#3A2616" stroke-width="2.2"/><text x="20" y="25" font-size="13" text-anchor="middle" fill="#3A2616">${ar(n)}</text></svg><small>الخانة ${ar(n)}</small></span>`;
/* order[] holds an item key or null for each slot; tokens not on a slot sit in the tray. after(order) runs after every move. */
function mxOrderBoard(host,keys,label,order,after,opt={}){
 const tok=k=>`<button class="mk-tok" data-tok="${k}">${mxChip(k,label(k))}</button>`;
 const paint=()=>{host.querySelectorAll('[data-slot]').forEach(s=>{const q=+s.dataset.slot;s.innerHTML=order[q]?tok(order[q]):`<i>${ar(q+1)}</i>`;s.classList.toggle('full',!!order[q]);});host.querySelector('[data-tray]').innerHTML=keys.filter(k=>!order.includes(k)).map(tok).join('');};
 host.innerHTML=`<div class="mk-line ${opt.ltr?'ltr':''}" style="--n:${order.length}">${order.map((_,q)=>`<div class="mk-slot tl" data-slot="${q}" tabindex="0" aria-label="${opt.slotName?opt.slotName(q):'الموضع '+ar(q+1)}"></div>`).join('')}</div><div class="mk-tray" data-tray="t" aria-label="القطع"></div>`;
 if(window.MK)MK.attach(host,{canDrag:()=>!(gameState&&gameState.finished),drop:(k,slot)=>{const from=order.indexOf(k);if(slot==null){if(from>=0)order[from]=null;}else{const q=+slot;if(from>=0)order[from]=order[q];order[q]=k;}gameState.moves=(gameState.moves||0)+1;paint();after(order);}});
 paint();return{paint,set(arr){arr.forEach((k,q)=>order[q]=k);paint();after(order);}};
}

// Stage 07 — drag the five tools onto the shelf; the clues are pictograms; the sand runs for 45 seconds.
function gameTimed(i){const target=L.timedItems.slice();gameState.order=[null,null,null,null,null];timerLeft=45;
 const clues=`<div class="mk-clues ex10-mk-clues"><div class="mk-clue">${mxChip('map',itemNames.map,1)}${mxRel('قبل')}${mxChip('compass',itemNames.compass,1)}</div><div class="mk-clue">${mxChip('compass',itemNames.compass,1)}${mxRel('مباشرة قبل')}${mxChip('lantern',itemNames.lantern,1)}</div><div class="mk-clue">${mxChip('lantern',itemNames.lantern,1)}${mxRel('قبل')}${mxChip('telescope',itemNames.telescope,1)}</div><div class="mk-clue">${mxChip('key',itemNames.key,1)}${mxRel('=')}${mxSlotMark(5)}</div></div>`;
 root.innerHTML=commonGame(i,`${clues}<div class="ex10-controls"><span class="ex10-timer" id="ex10-timer">٠٠:٤٥</span><b>اسحب الأدوات إلى الرف، من الأول إلى الخامس</b></div><div class="mk-board ex10-mk" id="ex10-shelf"></div>`);bindCommon(i);
 const board=mxOrderBoard($('#ex10-shelf',root),target.slice().sort(),k=>itemNames[k],gameState.order,o=>{if(o.every(Boolean)){if(o.join('|')===target.join('|'))winStage(i,'رتبت الأدوات قبل أن ينفد الرمل، وانفتح باب الورشة.');else feedback('الرف ممتلئ لكن الترتيب يخالف نقشًا: راجع العلاقات المصوّرة.','bad');}},{slotName:q=>'الخانة '+ar(q+1)});
 gameState.solve=()=>board.set(target);
 timerId=setInterval(()=>{if(view!=='game'||active!==i||gameState.finished){stopTimer();return;}timerLeft--;const t=$('#ex10-timer',root);if(t){t.textContent='٠٠:'+ar(Math.max(0,timerLeft).toString().padStart(2,'0'));t.classList.toggle('low',timerLeft<=10);}if(timerLeft===10)updateCrew(['alert','worried','alert'],['نهى','لم يبقَ سوى عشر ثوانٍ! ثبّت الترتيب الآن.']);if(timerLeft<=0){stopTimer();failStage(i,'انتهى الوقت قبل ترتيب الأدوات. راجع العلاقات بين الخريطة والبوصلة والفانوس ثم حاول مجدداً.');}},1000);}

function graphPuzzle(i,graph,nodes,solution,containerId){const edges=[];Object.keys(graph).forEach(a=>graph[a].forEach(b=>{if(a<b&&!edges.some(e=>e[0]===b&&e[1]===a))edges.push([a,b]);}));gameState.path=[solution[0]];const board=`<p class="ex10-objective">اختر الجزر المتصلة من موقعك الحالي حتى المرفأ. يمكنك الرجوع إلى المحطة السابقة عند الحاجة.</p><div class="ex10-graph" id="${containerId}"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${edges.map(([a,b])=>{const n=nodes.find(x=>x[0]===a),m=nodes.find(x=>x[0]===b);return `<line data-edge="${a}-${b}" x1="${n[2]}" y1="${n[3]}" x2="${m[2]}" y2="${m[3]}"/>`;}).join('')}</svg>${nodes.map(n=>`<button class="ex10-graph-node ${n[4]?'decoy':''}" data-graph-node="${n[0]}" style="left:${n[2]}%;top:${n[3]}%">${n[5]}<small>${n[1]}</small></button>`).join('')}</div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-graph">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-graph">إعادة المسار</button></div>`;root.innerHTML=commonGame(i,board);bindCommon(i);function paint(){root.querySelectorAll('[data-graph-node]').forEach(b=>{b.classList.toggle('visited',gameState.path.includes(b.dataset.graphNode));b.classList.toggle('active',b.dataset.graphNode===gameState.path.at(-1));});root.querySelectorAll('#'+containerId+' line').forEach(line=>{const [a,b]=line.dataset.edge.split('-');line.classList.toggle('route-done',gameState.path.includes(a)&&gameState.path.includes(b)&&Math.abs(gameState.path.indexOf(a)-gameState.path.indexOf(b))===1);});}
 root.querySelectorAll('[data-graph-node]').forEach(b=>b.onclick=()=>{const n=b.dataset.graphNode,p=gameState.path,last=p.at(-1);if(p.length>1&&n===p[p.length-2]){p.pop();paint();return;}if((graph[last]||[]).includes(n)&&!p.includes(n)){p.push(n);gameState.moves++;paint();if(n===solution[solution.length-1]){if(p.join('|')===solution.join('|'))winStage(i,'وصلت السفينة إلى المرفأ عبر الطريق البحري الوحيد الآمن.');else feedback('وصلت إلى المرفأ لكنك لم تتبع جميع العلامات. راجع المسار.','bad');}else if(nodes.find(x=>x[0]===n)?.[4]){gameState.errors++;feedback('وصلت إلى جزيرة شعاب مسدودة. تراجع واختر ممراً آخر.','bad');}else feedback('المسار صحيح حتى الآن. تابع إلى الجزيرة التالية.','good');}else feedback('لا يوجد ممر بحري مباشر من موقعك إلى هذه الجزيرة.','bad');});root.querySelector('[data-ex10="undo-graph"]').onclick=()=>{if(gameState.path.length>1){gameState.path.pop();paint();}};root.querySelector('[data-ex10="reset-graph"]').onclick=()=>{gameState.path=[solution[0]];paint();};paint();}
function gameIslands(i){
 const nodes=[['S','الميناء',12,53,'⚓'],['A','النخلة',30,21,'🌴'],['B','الشعاب',49,53,'🪸'],['C','القوس',67,20,'🏛'],['D','المنارة',69,78,'🗼'],['E','المرفأ',91,49,'🏁']];
 gameState.links=[];const links=L.islandLinks;
 const board=`<p class="ex10-objective">اختر خمسة حبال لربط الجزر الست. يجب أن تصل كل جزيرة إلى الشبكة، وألا يتجاوز مجموع الأطوال ١٥ علامة. تكوين الحلقة يستهلك حبلاً دون أن يضيف جزيرة جديدة.</p><div class="ex10-graph" id="ex10-island-net"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${links.map((e,k)=>{const a=nodes.find(n=>n[0]===e[0]),b=nodes.find(n=>n[0]===e[1]);return `<line data-link-line="${k}" x1="${a[2]}" y1="${a[3]}" x2="${b[2]}" y2="${b[3]}"/>`;}).join('')}</svg>${nodes.map(n=>`<div class="ex10-graph-node" style="left:${n[2]}%;top:${n[3]}%">${n[4]}<small>${n[1]}</small></div>`).join('')}</div><div class="ex10-clues"><div class="ex10-clue">الروابط المختارة: <b id="ex10-link-count">٠ / ٥</b></div><div class="ex10-clue">الميزانية المستهلكة: <b id="ex10-link-cost">٠ / ١٥</b></div></div><div class="ex10-sortlist" id="ex10-link-options">${links.map((e,k)=>`<button class="ex10-sortrow" data-island-link="${k}"><span class="item">${nodes.find(n=>n[0]===e[0])[1]} ↔ ${nodes.find(n=>n[0]===e[1])[1]}</span><b>${ar(e[2])} علامات</b></button>`).join('')}</div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="clear-links">مسح الروابط</button><button class="ex10-btn" data-ex10="check-links">اختبر الشبكة</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);function paint(){const cost=gameState.links.reduce((n,k)=>n+links[k][2],0);$('#ex10-link-count',root).textContent=ar(gameState.links.length)+' / ٥';$('#ex10-link-cost',root).textContent=ar(cost)+' / ١٥';root.querySelectorAll('[data-island-link]').forEach(b=>{b.classList.toggle('selected',gameState.links.includes(+b.dataset.islandLink));});root.querySelectorAll('[data-link-line]').forEach(line=>line.classList.toggle('route-done',gameState.links.includes(+line.dataset.linkLine)));}root.querySelectorAll('[data-island-link]').forEach(b=>b.onclick=()=>{const k=+b.dataset.islandLink;if(gameState.links.includes(k))gameState.links=gameState.links.filter(x=>x!==k);else if(gameState.links.length<5)gameState.links.push(k);else feedback('اكتملت خمسة حبال. أزل رابطاً قبل اختيار غيره.','bad');gameState.moves++;paint();});root.querySelector('[data-ex10="clear-links"]').onclick=()=>{gameState.links=[];paint();};root.querySelector('[data-ex10="check-links"]').onclick=()=>{const chosen=gameState.links.map(k=>links[k]),cost=chosen.reduce((n,e)=>n+e[2],0),seen=new Set(['S']);let changed=true;while(changed){changed=false;chosen.forEach(([a,b])=>{if(seen.has(a)&&!seen.has(b)){seen.add(b);changed=true;}if(seen.has(b)&&!seen.has(a)){seen.add(a);changed=true;}});}if(chosen.length===5&&seen.size===6&&cost<=15){winStage(i,'وصلت الجزر الست بخمسة حبال فقط، وبأقل كلفة ممكنة: ١٥ علامة.');}else{gameState.errors++;feedback(`الشبكة غير مكتملة أو مكلفة أكثر من اللازم. الجزر المتصلة: ${ar(seen.size)} / ٦ · الكلفة ${ar(cost)}.`, 'bad');}};paint();
}
function gameArchiveGrid(i){gameState.cells=Array.from({length:4},()=>[0,0,0,0]);const rows=L.nonogramTarget?L.nonogramSolutions().rows:[[3],[2],[3],[1]],cols=L.nonogramSolutions().cols;const rowText=rows.map(x=>x.join(' ')).join(' · '),colText=cols.map(x=>x.join(' ')).join(' | ');const board=`<div class="ex10-clues"><div class="ex10-clue">أدلة الصفوف (من الأعلى إلى الأسفل): <b>${rowText}</b></div><div class="ex10-clue">أدلة الأعمدة (من اليسار إلى اليمين): <b>${colText}</b></div></div><p class="ex10-objective">كل رقم يحدد طول مجموعة متصلة من الخانات المضيئة. أكمل الشبكة بحيث تتطابق أدلة الصفوف والأعمدة معاً.</p><div class="ex10-nonogram-wrap"><div class="ex10-nonogram-colclues">${cols.map(c=>`<span>${c.join(' · ')}</span>`).join('')}</div><div class="ex10-nonogram-grid" id="ex10-nonogram-grid">${gameState.cells.flatMap((row,r)=>row.map((v,c)=>`<button class="ex10-nonogram-cell" data-cell="${r}-${c}" aria-label="صف ${ar(r+1)} عمود ${ar(c+1)}"></button>`)).join('')}</div><div class="ex10-nonogram-rowclues">${rows.map((c,r)=>`<span>${c.join(' · ')}</span>`).join('')}</div></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="clear-grid">مسح الشبكة</button><button class="ex10-btn" data-ex10="check-grid">تحقق من النقش</button></div>`;root.innerHTML=commonGame(i,board);bindCommon(i);function paint(){root.querySelectorAll('[data-cell]').forEach(b=>{const [r,c]=b.dataset.cell.split('-').map(Number);b.classList.toggle('filled',!!gameState.cells[r][c]);});}root.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const [r,c]=b.dataset.cell.split('-').map(Number);gameState.cells[r][c]^=1;gameState.moves++;paint();});root.querySelector('[data-ex10="clear-grid"]').onclick=()=>{gameState.cells=Array.from({length:4},()=>[0,0,0,0]);paint();};root.querySelector('[data-ex10="check-grid"]').onclick=()=>{const ok=gameState.cells.every((row,r)=>row.every((v,c)=>v===L.nonogramTarget[r][c]));if(ok)winStage(i,'أعدت بناء نقش القبطان؛ صفوفه وأعمدته تطابقت مع جميع القرائن.');else{gameState.errors++;feedback('النقش لا يطابق الأدلة بعد. افحص مجموعات الخانات المتجاورة أفقياً وعمودياً.','bad');}};}
// The route is read from a compass strip, not from sentences. "تراجع" removes the last link.
function gameStars(i){const nodes=[['N','الشمال',50,11,false,'✦'],['W','الغرب',19,33,false,'✦'],['SW','الجنوب الغربي',30,75,false,'✦'],['SE','الجنوب الشرقي',70,75,false,'✦'],['E','الشرق',81,33,false,'✦'],['S','الجنوب',50,91,false,'✦'],['X','نجم شارد',47,46,true,'✧'],['Y','وهج جانبي',9,73,true,'✧'],['Z','وميض بعيد',92,61,true,'✧']];const solution=['N','W','SW','SE','E','S'];gameState.path=['N'];const edges=[['N','W'],['W','SW'],['SW','SE'],['SE','E'],['E','S'],['W','X'],['SW','Y'],['E','Z']];
 const ARW={N:'↑',W:'←',SW:'↙',SE:'↘',E:'→',S:'↓'};
 const strip=`<div class="mk-compass" aria-label="ترتيب النجوم بالاتجاه حول القبة">${solution.map((n,k)=>`<span class="mk-cdir"><b>${ar(k+1)}</b><i>${ARW[n]}</i></span>`).join('')}</div>`;
 const board=`<p class="ex10-objective">ابدأ من النجم العلوي واسحب إصبعك عبر النجوم حسب أسهم البوصلة حول مركز القبة. يمكنك أيضًا لمس النجوم واحدًا بعد الآخر.</p>${strip}<div class="ex10-starfield" id="ex10-sf"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${edges.map(([a,b])=>{const x=nodes.find(n=>n[0]===a),y=nodes.find(n=>n[0]===b);return `<line data-star-edge="${a}-${b}" x1="${x[2]}" y1="${x[3]}" x2="${y[2]}" y2="${y[3]}"/>`;}).join('')}<polyline id="ex10-trail" points="" fill="none" stroke="#F2C553" stroke-width="1.6" stroke-linecap="round" vector-effect="non-scaling-stroke"/></svg>${nodes.map(n=>`<button class="ex10-star ${n[4]?'decoy':''}" data-star="${n[0]}" style="left:${n[2]}%;top:${n[3]}%">${n[5]}</button>`).join('')}</div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-star">تراجع عن آخر وصلة</button><button class="ex10-btn secondary" data-ex10="reset-star">إعادة المسار</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 const sf=$('#ex10-sf',root),pt=id=>{const n=nodes.find(x=>x[0]===id);return n[2]+','+n[3];};
 function paint(){root.querySelectorAll('[data-star]').forEach(b=>{b.classList.toggle('visited',gameState.path.includes(b.dataset.star));b.classList.toggle('head',gameState.path.at(-1)===b.dataset.star);});root.querySelectorAll('[data-star-edge]').forEach(l=>{const [a,b]=l.dataset.starEdge.split('-'),p=gameState.path,ia=p.indexOf(a),ib=p.indexOf(b);l.classList.toggle('route-done',ia>=0&&ib>=0&&Math.abs(ia-ib)===1);});$('#ex10-trail',root).setAttribute('points',gameState.path.map(pt).join(' '));root.querySelectorAll('.mk-cdir').forEach((c,k)=>c.classList.toggle('done',k<gameState.path.length));}
 function visit(n,silent){const p=gameState.path,last=p.at(-1);if(gameState.finished||n===last)return;if(p.length>1&&n===p[p.length-2]){if(silent)return;p.pop();paint();return;}
  if(edges.some(([a,b])=>a===last&&b===n)&&!p.includes(n)){p.push(n);gameState.moves++;paint();if(p.length===solution.length){if(p.join('|')===solution.join('|'))winStage(i,'اكتمل مسار النجوم وأضاء قلب أَثْران.');else feedback('المسار لا يطابق أسهم البوصلة. تراجع عن آخر وصلة وجرّب.','bad');}}
  else if(!silent)feedback('هذا النجم لا يتصل بآخر نجم في مسارك.','bad');}
 let drawing=false;
 sf.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-star]');if(!b)return;drawing=true;try{sf.setPointerCapture(e.pointerId);}catch(_){}if(b.dataset.star!==gameState.path.at(-1))visit(b.dataset.star);e.preventDefault();});
 sf.addEventListener('pointermove',e=>{if(!drawing)return;const el=document.elementFromPoint(e.clientX,e.clientY),b=el&&el.closest&&el.closest('[data-star]');if(b&&sf.contains(b)){/* a sliding finger links a star only near its centre, so grazing a neighbour on the way does not add or undo a link */const r=b.getBoundingClientRect();if(Math.hypot(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2)<=r.width*.34)visit(b.dataset.star,true);}});
 const stop=()=>{drawing=false;};sf.addEventListener('pointerup',stop);sf.addEventListener('pointercancel',stop);
 root.querySelector('[data-ex10="undo-star"]').onclick=()=>{if(gameState.path.length>1){gameState.path.pop();paint();}};root.querySelector('[data-ex10="reset-star"]').onclick=()=>{gameState.path=['N'];paint();};
 gameState.solve=()=>solution.slice(1).forEach(n=>visit(n));paint();}

// Stage 11 — rotate seven pipe pieces to connect the source to the cistern.
function gamePipes(i){
 gameState.orient=L.pipeTiles.map(t=>t.initial);
 const tileAt=new Map(L.pipeTiles.map((t,k)=>[`${t.r},${t.c}`,{...t,k}]));
 const cellHtml=(r,c)=>{
  if(r===2&&c===0)return '<div class="ex10-pipe-end source" aria-label="مدخل الماء">⛲<small>مدخل</small></div>';
  if(r===2&&c===4)return '<div class="ex10-pipe-end goal" aria-label="المصب">🚰<small>المصب</small></div>';
  const t=tileAt.get(`${r},${c}`);if(!t)return '<div class="ex10-pipe-empty"></div>';
  const rot=gameState.orient[t.k]*90,shape=t.type==='corner'?'M50 50 L50 10 M50 50 L90 50':'M50 50 L50 10 M50 50 L50 90';
  return `<button class="ex10-pipe-tile ${t.type}" data-pipe="${t.k}" aria-label="تدوير قطعة الأنبوب ${t.id}"><svg viewBox="0 0 100 100" aria-hidden="true"><g transform="rotate(${rot} 50 50)"><path d="${shape}"/><circle cx="50" cy="50" r="13"/></g></svg><small>${t.id}</small></button>`;
 };
 const board=`<p class="ex10-objective">اضغط على أي قطعة لتدويرها ربع دورة. يجب أن تتصل كل نهايات الأنابيب، من المدخل إلى المصب، دون أي تسرب.</p><div class="ex10-pipe-board" id="ex10-pipe-board">${Array.from({length:5},(_,r)=>Array.from({length:5},(_,c)=>cellHtml(r,c)).join('')).join('')}</div><div class="ex10-clues"><div class="ex10-clue">المسار ينعطف إلى الأسفل بعد القطعة الأولى.</div><div class="ex10-clue">الجزء السفلي من المسار يمتد أفقياً قبل أن يصعد إلى المصب.</div></div><div class="ex10-controls"><button class="ex10-btn" data-ex10="check-pipes">اختبر تدفق الماء</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){root.querySelectorAll('[data-pipe]').forEach(b=>{const k=+b.dataset.pipe,t=L.pipeTiles[k];b.querySelector('g')?.setAttribute('transform',`rotate(${gameState.orient[k]*90} 50 50)`);b.classList.toggle('aligned',gameState.orient[k]===t.target);});}
 root.querySelectorAll('[data-pipe]').forEach(b=>b.onclick=()=>{if(gameState.finished)return;const k=+b.dataset.pipe,t=L.pipeTiles[k],mod=t.type==='corner'?4:2;gameState.orient[k]=(gameState.orient[k]+1)%mod;gameState.moves++;paint();if(L.pipeIsSolved(gameState.orient))winStage(i,'اتصلت الأنابيب السبعة بلا تسرب، واندفع الماء إلى المصب.');else feedback('تغيّر اتجاه الوصلة. راقب الطرفين قبل تدوير القطعة التالية.','good');});
 root.querySelector('[data-ex10="check-pipes"]').onclick=()=>{if(L.pipeIsSolved(gameState.orient))winStage(i,'اكتمل مسار الماء من المدخل إلى المصب دون أي تسرب.');else{gameState.errors++;feedback('ما زال هناك طرف مفتوح أو وصلة لا تقابل جارتها. افحص المسار من المدخل.','bad');}};paint();
}

// Stage 12 — sliding on ice; the only seven-slide shortest route is verified by BFS.
function gameIce(i){
 gameState.icePos=L.iceStart.slice();gameState.iceTrail=[L.iceStart.slice()];gameState.iceDirections=[];gameState.iceCount=0;
 const board=`<p class="ex10-objective">البلورة تنزلق حتى تصطدم بصخرة أو حافة. أوصلها إلى البوابة في سبع انزلاقات بالضبط. يمكنك التراجع عن الحركة الأخيرة.</p><div class="ex10-ice-board" id="ex10-ice-board"></div><div class="ex10-ice-status"><span>الانزلاقات: <b id="ex10-ice-count">٠ / ٧</b></span><span>الموقع الحالي: <b id="ex10-ice-pos">أسفل اليسار</b></span></div><div class="ex10-ice-controls"><button class="ex10-btn secondary" data-ice-move="up">↑ أعلى</button><button class="ex10-btn secondary" data-ice-move="left">← يسار</button><button class="ex10-btn secondary" data-ice-move="down">↓ أسفل</button><button class="ex10-btn secondary" data-ice-move="right">يمين →</button></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-ice">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-ice">إعادة المسار</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 const posName=([r,c])=>r===4&&c===0?'نقطة البداية':r===0&&c===4?'بوابة الخروج':`الصف ${ar(r+1)} · العمود ${ar(c+1)}`;
 function paint(){const boardEl=$('#ex10-ice-board',root);if(!boardEl)return;boardEl.innerHTML=Array.from({length:5},(_,r)=>Array.from({length:5},(_,c)=>{const rock=L.iceObstacles.some(([a,b])=>a===r&&b===c),player=gameState.icePos[0]===r&&gameState.icePos[1]===c,goal=L.iceGoal[0]===r&&L.iceGoal[1]===c;return `<div class="ex10-ice-cell ${rock?'rock':''} ${goal?'goal':''} ${player?'player':''}">${player?'🔷':goal?'🏁':rock?'🪨':''}</div>`;}).join('')).join('');$('#ex10-ice-count',root).textContent=ar(gameState.iceCount)+' / ٧';$('#ex10-ice-pos',root).textContent=posName(gameState.icePos);root.querySelectorAll('[data-ice-move]').forEach(b=>b.disabled=gameState.finished);}
 function move(dir){if(gameState.finished)return;const next=L.iceMoves(gameState.icePos).find(m=>m.move===dir);if(!next){feedback('هذا الاتجاه مغلق؛ البلورة لا تتحرك من موضعها الحالي.','bad');return;}gameState.iceTrail.push(gameState.icePos.slice());gameState.icePos=next.to.slice();gameState.iceDirections.push(dir);gameState.iceCount++;gameState.moves++;paint();if(gameState.icePos[0]===L.iceGoal[0]&&gameState.icePos[1]===L.iceGoal[1]){if(gameState.iceCount===7&&gameState.iceDirections.join('|')===L.iceAudit().path.join('|'))winStage(i,'وصلت البلورة إلى البوابة في المسار الأدنى الوحيد: سبع انزلاقات.');else failStage(i,'وصلت إلى البوابة، لكنك استهلكت حركات أكثر من المسار الأمثل. أعد المحاولة بخطة أدق.');return;}if(gameState.iceCount>=7)failStage(i,'انتهت الحركات السبع قبل الوصول إلى البوابة. راجع العوائق وخطط للمسار قبل الانزلاق.');else feedback('انزلقت البلورة حتى أول عائق. اقرأ موضعها الجديد قبل الحركة التالية.','good');}
 root.querySelectorAll('[data-ice-move]').forEach(b=>b.onclick=()=>move(b.dataset.iceMove));
 root.querySelector('[data-ex10="undo-ice"]').onclick=()=>{if(gameState.finished||!gameState.iceTrail.length)return;gameState.icePos=gameState.iceTrail.pop();gameState.iceDirections.pop();gameState.iceCount=Math.max(0,gameState.iceCount-1);paint();feedback('تم التراجع عن الانزلاق الأخير.','');};
 root.querySelector('[data-ex10="reset-ice"]').onclick=()=>{gameState.icePos=L.iceStart.slice();gameState.iceTrail=[L.iceStart.slice()];gameState.iceDirections=[];gameState.iceCount=0;paint();feedback('أعيد المسار إلى نقطة البداية.','');};paint();
}

// Stage 13 — Nim strategy against an optimal opponent.
function gameNim(i){
 gameState.heaps=[1,3,5];gameState.aiPending=false;gameState.playerHasAdvantage=false;
 const board=`<p class="ex10-objective">ثلاث أكوام من الحراشف: ١ و٣ و٥. خذ من كومة واحدة أي عدد من ١ حتى كامل الكومة في دورك. من يأخذ آخر حرشفة يفوز. الحارس يرد بعدك بأفضل حركة يستطيعها.</p><div class="ex10-clues"><div class="ex10-clue">لا يكفي أن تترك مجموعاً صغيراً؛ المطلوب أن تترك الخصم في وضع لا يملك منه رداً رابحاً.</div><div class="ex10-clue">يمكنك أخذ أي عدد متاح من كومة واحدة فقط في كل دور.</div></div><div id="ex10-nim-heaps" class="ex10-nim-heaps"></div><div class="ex10-nim-note" id="ex10-nim-note">اختر عدد الحراشف التي تريد أخذها من إحدى الأكوام.</div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function heapHtml(){return gameState.heaps.map((n,k)=>`<section class="ex10-nim-heap"><b>الكومة ${ar(k+1)}</b><div class="ex10-nim-stones">${Array.from({length:n},()=>'<span>◆</span>').join('')||'<small>فارغة</small>'}</div><div class="ex10-nim-takes">${Array.from({length:n},(_,z)=>z+1).map(t=>`<button class="ex10-btn secondary" data-nim-pile="${k}" data-nim-take="${t}" ${gameState.aiPending?'disabled':''}>خذ ${ar(t)}</button>`).join('')}</div></section>`).join('');}
 function paint(){const el=$('#ex10-nim-heaps',root);if(el)el.innerHTML=heapHtml();}
 function bindMoves(){root.querySelectorAll('[data-nim-pile]').forEach(b=>b.onclick=()=>playerMove(+b.dataset.nimPile,+b.dataset.nimTake));}
 function total(){return gameState.heaps.reduce((a,b)=>a+b,0);}
 function playerMove(pile,take){if(gameState.finished||gameState.aiPending||take>gameState.heaps[pile])return;const was=gameState.heaps.slice();gameState.heaps[pile]-=take;gameState.moves++;gameState.playerHasAdvantage=gameState.moves===1&&L.nimWinningMoves(was).some(m=>m.pile===pile&&m.take===take);if(total()===0){winStage(i,'أخذت آخر حرشفة وفزت برهان القاعة.');return;}gameState.aiPending=true;paint();bindMoves();$('#ex10-nim-note',root).textContent=gameState.playerHasAdvantage?'اختيار محسوب؛ تركت الحارس في وضع لا يملك منه افتتاحية رابحة.':'الحارس يراقب الأكوام ويحاول استعادة التوازن…';updateCrew(['thinking','happy','curious'],['نهى','اختيار ذكي؛ راقبي كيف سيرد الحارس الآن.']);previewTimer=setTimeout(()=>{if(gameState.finished||view!=='game'||active!==i)return;const reply=L.nimBestMove(gameState.heaps);if(!reply){winStage(i,'لم تبقَ حراشف للحارس؛ فزت بالرهان.');return;}gameState.heaps=reply.remaining;gameState.moves++;gameState.aiPending=false;paint();bindMoves();if(total()===0){failStage(i,'أخذ الحارس آخر حرشفة. حاول أن تترك له وضعاً لا يستطيع كسره.');return;}$('#ex10-nim-note',root).textContent=`الحارس أخذ ${ar(reply.take)} من الكومة ${ar(reply.pile+1)}. دورك الآن؛ ابحث عن الحركة التي تعيد التوازن.`;feedback('رد الحارس محسوب. راجع الأكوام الثلاث قبل اتخاذ القرار التالي.','good');},550);}
 paint();bindMoves();
}

// Stage 14 — infer three lantern directions from silhouettes and relational clues.
function gameShadows(i){
 const dirs=['شمال','شرق','جنوب','غرب'],shapes=[['🦅','🦀','🚢','🐋'],['🐢','🐚','🦈','🐙'],['🌙','🪸','⭐','⚓']],labels=['الفانوس الأول','الفانوس الثاني','الفانوس الثالث'];gameState.shadow=[0,0,0];
 const board=`<p class="ex10-objective">اضبط الفوانيس حتى تطابق الظلال الثلاثة النقوش على الجدار: سفينة، سلحفاة، ومرساة. استخدم العلاقة بين اتجاهات الفوانيس ولا تعتمد على التخمين.</p><div class="ex10-shadow-targets"><span>🚢</span><span>🐢</span><span>⚓</span></div><div class="ex10-clues"><div class="ex10-clue">الأول يعطي ظل السفينة.</div><div class="ex10-clue">الثاني عكس اتجاه الأول تماماً.</div><div class="ex10-clue">الثالث ربع دورة مع عقارب الساعة من الأول.</div></div><div class="ex10-shadow-lamps">${labels.map((t,k)=>`<section class="ex10-shadow-lamp"><b>${t}</b><div class="shadow-shape" id="ex10-shadow-shape${k}">${shapes[k][0]}</div><strong id="ex10-shadow-dir${k}">شمال</strong><button class="ex10-btn secondary" data-shadow="${k}">دوّر الفانوس ↻</button></section>`).join('')}</div><div class="ex10-controls"><button class="ex10-btn" data-ex10="check-shadows">اختبر الظلال</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){for(let k=0;k<3;k++){$('#ex10-shadow-shape'+k,root).textContent=shapes[k][gameState.shadow[k]];$('#ex10-shadow-dir'+k,root).textContent=dirs[gameState.shadow[k]];}}
 root.querySelectorAll('[data-shadow]').forEach(b=>b.onclick=()=>{const k=+b.dataset.shadow;gameState.shadow[k]=(gameState.shadow[k]+1)%4;gameState.moves++;paint();if(JSON.stringify(gameState.shadow)===JSON.stringify(L.shadowTarget))winStage(i,'اصطفّت ظلال السفينة والسلحفاة والمرساة مع النقوش الثلاثة.');});
 root.querySelector('[data-ex10="check-shadows"]').onclick=()=>{if(JSON.stringify(gameState.shadow)===JSON.stringify(L.shadowTarget))winStage(i,'وصلت الفوانيس إلى اتجاهاتها الصحيحة وأضاء ختم المعبد.');else{gameState.errors++;feedback('الظلال لم تصطف بعد. تذكّر أن الفانوس الثاني عكس الأول، والثالث يدور معه باتجاه عقارب الساعة.','bad');}};paint();
}

// Stage 15 — rotate the Arabic Caesar wheel and decode the captain's bottle.
function gameCipher(i){gameState.cipherShift=0;const alphabet=L.arabicCipherAlphabet.join(' · ');
 const board=`<p class="ex10-objective">النص المشفّر على الورقة: <b class="ex10-cipher-text">${L.cipherText}</b>. تقول القرينة المحفورة على عنق الزجاجة إن الحرف <b>ا</b> في الرسالة الأصلية أصبح <b>ج</b> في الشفرة. أدر القرص وفق ترتيب الحروف ثم اقرأ الرسالة.</p><div class="ex10-clues"><div class="ex10-clue">ترتيب القرص: ${alphabet}</div><div class="ex10-clue">جميع الحروف تحركت بالمقدار نفسه وفي الاتجاه نفسه عند التشفير.</div></div><div class="ex10-cipher-disc"><div class="cipher-ring">◉</div><div class="cipher-offset"><span>إزاحة القرص</span><strong id="ex10-cipher-shift">٠</strong></div><div class="ex10-cipher-controls"><button class="ex10-btn secondary" data-cipher="down">↶</button><button class="ex10-btn secondary" data-cipher="up">↷</button></div><div class="ex10-cipher-output"><small>الرسالة بعد فك الشفرة</small><b id="ex10-cipher-decoded">${L.shiftArabic(L.cipherText,0)}</b></div></div><div class="ex10-controls"><button class="ex10-btn" data-ex10="check-cipher">افتح الرسالة</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){gameState.cipherShift=(gameState.cipherShift+L.arabicCipherAlphabet.length)%L.arabicCipherAlphabet.length;$('#ex10-cipher-shift',root).textContent=ar(gameState.cipherShift);$('#ex10-cipher-decoded',root).textContent=L.shiftArabic(L.cipherText,-gameState.cipherShift);}
 root.querySelectorAll('[data-cipher]').forEach(b=>b.onclick=()=>{const d=b.dataset.cipher==='up'?1:-1;gameState.cipherShift=(gameState.cipherShift+d+L.arabicCipherAlphabet.length)%L.arabicCipherAlphabet.length;gameState.moves++;paint();});
 root.querySelector('[data-ex10="check-cipher"]').onclick=()=>{const decoded=L.shiftArabic(L.cipherText,-gameState.cipherShift);if(decoded===L.cipherPlain&&gameState.cipherShift===L.cipherShift)winStage(i,'فُكّت رسالة القبطان: الميناء. لقد كشفت الرسالة الطريق إلى قصر المرايا.');else{gameState.errors++;feedback('الرسالة ما زالت غير مفهومة. ثبّت علاقة ا ← ج ثم احسب الإزاحة نفسها لبقية الحروف.','bad');updateCrew(['thinking','worried','curious'],['رواء','لدينا قرينة مؤكدة؛ لا نحتاج إلى تجربة كل الحروف عشوائياً.']);}};paint();
}


// Stage 16 — uniquely match four recovered cargo crates to the four berths.
function gameManifest(i){
 const items=L.manifestItems;gameState.manifest=[null,null,null,null];
 const clues=`<div class="mk-clues ex10-mk-clues"><div class="mk-clue">${mxChip('بلور','بلور',1)}${mxRel('مباشرة قبل')}${mxChip('بوصلة','بوصلة',1)}</div><div class="mk-clue">${mxChip('لؤلؤ','لؤلؤ',1)}${mxRel('ليس')}${mxSlotMark(1)}${mxRel('ولا')}${mxSlotMark(4)}</div><div class="mk-clue">${mxChip('توابل','توابل',1)}${mxRel('بعد')}${mxChip('لؤلؤ','لؤلؤ',1)}</div></div>`;
 root.innerHTML=commonGame(i,`<p class="ex10-objective">اسحب كل صندوق إلى رصيف. كل صندوق مرة واحدة، والقرائن الثلاث تتحقق معًا.</p>${clues}<div class="mk-board ex10-mk" id="ex10-docks"></div><div class="ex10-controls"><button class="ex10-btn" data-ex10="check-manifest">اعتماد سجل الحمولة</button></div>`);bindCommon(i);
 const board=mxOrderBoard($('#ex10-docks',root),items,k=>k,gameState.manifest,()=>{},{slotName:q=>'الرصيف '+ar(q+1)});
 gameState.solve=()=>board.set(L.manifestSolutions?L.manifestSolutions()[0]:['بلور','بوصلة','لؤلؤ','توابل']);
 root.querySelector('[data-ex10="check-manifest"]').onclick=()=>{const orderNow=gameState.manifest.slice();if(orderNow.some(x=>!x)){feedback('ضع صندوقًا على كل رصيف أولًا.','bad');return;}if(L.manifestValid(orderNow))winStage(i,'تطابق سجل الشحن: البلور، ثم البوصلة، فاللؤلؤ، وأخيراً التوابل. عُثر على ختم الميناء.');else{gameState.errors++;feedback('الترتيب لا يحقق جميع القرائن بعد. انظر إلى القرينة التي تخالفها.','bad');}};
}

// Stage 17 — timed tidal wheel. The safe sector sequence is derived from the three clues.
function gameTideClock(i){
 gameState.tideSector=0;gameState.tideRound=0;gameState.tideTicks=0;gameState.tideSeconds=35;gameState.tideErrors=0;timerLeft=35;
 const board=`<p class="ex10-objective">يدور مؤشر ساعة المدّ بين ثمانية قطاعات. أوقفه عند النوافذ الثلاث بالترتيب؛ لكل نافذة لحظة واحدة في كل دورة.</p><div class="ex10-clues"><div class="ex10-clue">النافذة الأولى: قطاعان بعد علامة الشمال.</div><div class="ex10-clue">النافذة الثانية: ثلاثة قطاعات بعد النافذة الأولى.</div><div class="ex10-clue">النافذة الثالثة: أربعة قطاعات بعد النافذة الثانية. يبدأ العد من القطاع صفر.</div></div><div class="ex10-tide-stage"><div class="ex10-tide-wheel" id="ex10-tide-wheel">${Array.from({length:8},(_,k)=>`<div class="ex10-tide-sector" data-tide-sector="${k}"><b>${ar(k)}</b><small>${['شمال','شمال شرق','شرق','جنوب شرق','جنوب','جنوب غرب','غرب','شمال غرب'][k]}</small></div>`).join('')}</div><div class="ex10-tide-readout"><span>المؤشر الحالي</span><strong id="ex10-tide-current">٠</strong><span>النافذة <b id="ex10-tide-round">١ / ٣</b></span><span>الوقت <b id="ex10-tide-time">٣٥</b> ثانية</span></div><button class="ex10-btn ex10-tide-stop" data-ex10="stop-tide">أوقف الموجة الآن</button></div><div class="ex10-feedback" id="ex10-tide-status" aria-live="polite">راقب المؤشر، ثم أوقفه عند النافذة الأولى.</div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){root.querySelectorAll('[data-tide-sector]').forEach(el=>{const n=+el.dataset.tideSector;el.classList.toggle('current',n===gameState.tideSector);el.classList.toggle('passed',n===L.tideTargets[gameState.tideRound]&&gameState.tideRound>0);});$('#ex10-tide-current',root).textContent=ar(gameState.tideSector);$('#ex10-tide-round',root).textContent=ar(Math.min(3,gameState.tideRound+1))+' / ٣';$('#ex10-tide-time',root).textContent=ar(gameState.tideSeconds);}
 root.querySelector('[data-ex10="stop-tide"]').onclick=()=>{if(gameState.finished)return;const target=L.tideTargets[gameState.tideRound];if(gameState.tideSector===target){gameState.moves++;gameState.tideRound++;if(gameState.tideRound===3){winStage(i,'أوقفت الموجات الثلاث عند النوافذ الصحيحة: ٣ ثم ٦ ثم ٢. استقرت الساعة وفتحت البوابة البحرية.');return;}$('#ex10-tide-status',root).textContent='ضبط صحيح! استعد للنافذة التالية.';updateCrew(['thinking','happy','curious'],['نهى','أحسنت! الآن احسبي انتقال النافذة التالية.']);}else{gameState.errors++;gameState.tideErrors++;$('#ex10-tide-status',root).textContent='لم تتوقف الموجة في النافذة الصحيحة. أعيدي قراءة القرائن وانتظري الدورة التالية.';feedback('توقيت غير صحيح؛ بقيت لك '+ar(5-gameState.tideErrors)+' محاولات تنبيه.','bad');if(gameState.tideErrors>=5){failStage(i,'تجاوزت الموجة خمس محاولات إيقاف خاطئة. أعد المحاولة بعد حساب القطاعات.');return;}}paint();};
 paint();
 timerId=setInterval(()=>{if(view!=='game'||active!==i||gameState.finished){stopTimer();return;}gameState.tideTicks++;if(gameState.tideTicks%2===0){gameState.tideSeconds--;timerLeft=gameState.tideSeconds;}gameState.tideSector=(gameState.tideSector+1)%L.tideSectorCount;paint();if(gameState.tideSeconds===20)updateCrew(['alert','worried','thinking'],['نهى','بدأ المدّ يتسارع؛ تابعي القطاعات ولا تتعجلي.']);if(gameState.tideSeconds===10)updateCrew(['alert','worried','alert'],['نهى','عشر ثوانٍ فقط! استعدي للنافذة التالية.']);if(gameState.tideSeconds<=0){failStage(i,'ارتفع المد قبل تثبيت النوافذ الثلاث. أعيدي المحاولة مع تتبع تسلسل القطاعات.');}},500);
}

// Stage 18 — unique shortest 3x3 sliding relic puzzle.
function gameRelics(i){
 gameState.relics=L.relicStart.slice();gameState.relicTrail=[];
 const symbols={1:'⚓',2:'☀',3:'≈',4:'🧭',5:'◈',6:'☾',7:'✦',8:'🗝'};
 const board=`<p class="ex10-objective">حرّك الرقعة الملاصقة للفراغ فقط. أعد ترتيب الأختام من ١ إلى ٨ واترك الفراغ في الركن الأخير. لديك ثماني حركات، والحل الأقصر وحيد.</p><div class="ex10-relic-board" id="ex10-relic-board"></div><div class="ex10-relic-status"><span>الحركات <b id="ex10-relic-count">٠ / ٨</b></span><span>الهدف: ترتيب الأختام</span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-relic">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-relic">إعادة الرقع</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){const el=$('#ex10-relic-board',root);el.innerHTML=gameState.relics.map((v,k)=>v?`<button class="ex10-relic-tile" data-relic="${k}" aria-label="الرقعة ${ar(v)}"><b>${ar(v)}</b><span>${symbols[v]}</span></button>`:`<div class="ex10-relic-empty" aria-label="فراغ">✧</div>`).join('');$('#ex10-relic-count',root).textContent=ar(gameState.moves)+' / ٨';el.querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>{if(gameState.finished)return;const k=+b.dataset.relic,z=gameState.relics.indexOf(0);if(Math.abs(Math.floor(k/3)-Math.floor(z/3))+Math.abs(k%3-z%3)!==1){feedback('هذه الرقعة لا تلامس الفراغ؛ اختر رقعة مجاورة فقط.','bad');return;}gameState.relicTrail.push(gameState.relics.slice());[gameState.relics[k],gameState.relics[z]]=[gameState.relics[z],gameState.relics[k]];gameState.moves++;paint();if(gameState.relics.every((v,n)=>v===L.relicGoal[n])){if(gameState.moves===8)winStage(i,'اكتمل ختم المرايا في المسار الأقصر الوحيد: ثماني حركات.');else failStage(i,'اكتمل الترتيب بعد تجاوز حد الحركات الثماني؛ أعد المحاولة بخطة أقصر.');return;}if(gameState.moves>=8)failStage(i,'انتهت الحركات الثماني قبل اكتمال ختم المرايا.');});}
 root.querySelector('[data-ex10="undo-relic"]').onclick=()=>{if(gameState.finished||!gameState.relicTrail.length)return;gameState.relics=gameState.relicTrail.pop();gameState.moves=Math.max(0,gameState.moves-1);paint();feedback('أعدت الرقعة إلى موضعها السابق.','');};
 root.querySelector('[data-ex10="reset-relic"]').onclick=()=>{gameState.relics=L.relicStart.slice();gameState.relicTrail=[];gameState.moves=0;paint();feedback('عاد ختم المرايا إلى وضع البداية.','');};paint();
}

// Stage 19 — one-crate Sokoban-style push puzzle with a unique six-push solution.
function gameCrate(i){
 gameState.cratePlayer=L.crateStartPlayer.slice();gameState.crateBox=L.crateStartBox.slice();gameState.cratePushes=0;gameState.crateTrail=[];const open=new Set(L.crateOpen.map(p=>p.join(',')));
 const board=`<p class="ex10-objective">حرّك المستكشف داخل الممرات، وادفع الصندوق إلى منصة الختم. لا يمكن سحب الصندوق أو دفعه إلى جدار. المسارات المفتوحة فقط هي التي تسمح بالحركة.</p><div class="ex10-crate-board" id="ex10-crate-board"></div><div class="ex10-crate-status"><span>دفعات الصندوق <b id="ex10-crate-pushes">٠ / ٦</b></span><span>الهدف: المنصة الذهبية</span></div><div class="ex10-crate-controls"><button class="ex10-btn secondary" data-crate-move="up">↑</button><button class="ex10-btn secondary" data-crate-move="left">←</button><button class="ex10-btn secondary" data-crate-move="down">↓</button><button class="ex10-btn secondary" data-crate-move="right">→</button></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-crate">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-crate">إعادة المخزن</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){const el=$('#ex10-crate-board',root);el.innerHTML=Array.from({length:6},(_,r)=>Array.from({length:6},(_,c)=>{const k=`${r},${c}`,isOpen=open.has(k),player=gameState.cratePlayer[0]===r&&gameState.cratePlayer[1]===c,box=gameState.crateBox[0]===r&&gameState.crateBox[1]===c,goal=L.crateGoal[0]===r&&L.crateGoal[1]===c;return `<div class="ex10-crate-cell ${isOpen?'open':'wall'} ${goal?'goal':''} ${box?'box':''} ${player?'player':''}">${box?'📦':player?'🧭':goal?'⚓':''}</div>`;}).join('')).join('');$('#ex10-crate-pushes',root).textContent=ar(gameState.cratePushes)+' / ٦';root.querySelectorAll('[data-crate-move]').forEach(b=>b.disabled=gameState.finished);}
 const delta={up:[-1,0],down:[1,0],left:[0,-1],right:[0,1]};
 function move(dir){if(gameState.finished)return;const [dr,dc]=delta[dir],p=gameState.cratePlayer,b=gameState.crateBox,next=[p[0]+dr,p[1]+dc],inside=x=>open.has(x.join(','));if(!inside(next)){feedback('هذا الممر مغلق بالصخور أو الجدار.','bad');return;}let box=b.slice(),push=next[0]===b[0]&&next[1]===b[1];if(push){box=[b[0]+dr,b[1]+dc];if(!inside(box)){feedback('لا توجد مساحة خلف الصندوق لدفعه.','bad');return;}}gameState.crateTrail.push({p:p.slice(),b:b.slice(),pushes:gameState.cratePushes});gameState.cratePlayer=next;if(push)gameState.cratePushes++;gameState.crateBox=box;gameState.moves++;paint();if(box[0]===L.crateGoal[0]&&box[1]===L.crateGoal[1]){if(gameState.cratePushes===6)winStage(i,'وصل صندوق القبطان إلى منصة الختم بعد ست دفعات؛ لم تحتج إلى سحبه أو دفعه إلى طريق مسدود.');else failStage(i,'وصل الصندوق بعد عدد دفعات أكبر من الحل الأقصر. أعد المحاولة وخطط للممر.');return;}if(gameState.cratePushes>=6)failStage(i,'استهلكت الدفعات الست ولم يصل الصندوق إلى المنصة.');else feedback(push?'تحرك الصندوق. راقب موقعك الجديد قبل الدفعة التالية.':'تحرك المستكشف داخل الممر؛ اقترب من الجهة التي تسمح بالدفع.','good');}
 root.querySelectorAll('[data-crate-move]').forEach(b=>b.onclick=()=>move(b.dataset.crateMove));
 root.querySelector('[data-ex10="undo-crate"]').onclick=()=>{if(gameState.finished||!gameState.crateTrail.length)return;const p=gameState.crateTrail.pop();gameState.cratePlayer=p.p;gameState.crateBox=p.b;gameState.cratePushes=p.pushes;paint();feedback('تم التراجع عن الحركة الأخيرة.','');};
 root.querySelector('[data-ex10="reset-crate"]').onclick=()=>{gameState.cratePlayer=L.crateStartPlayer.slice();gameState.crateBox=L.crateStartBox.slice();gameState.cratePushes=0;gameState.crateTrail=[];gameState.moves=0;paint();feedback('عاد الصندوق والمستكشف إلى نقطة البداية.','');};paint();
}

// Stage 20 — knight route with three seals; the open-square graph is one induced path.
function gameKnight(i){
 gameState.knightIndex=0;gameState.knightMoves=0;gameState.knightTrail=[];gameState.knightSeals=[];const route=L.knightRoute,sealSet=new Set(L.knightSeals);const openSet=new Set(route.map(p=>p.join(',')));
 const board=`<p class="ex10-objective">تحرك كقطعة الفارس: مربعان في اتجاه وواحد جانبياً. اجمع الأختام الثلاثة بالترتيب، ثم صِل إلى بوابة الخروج في ثماني قفزات بالضبط. المربعات الداكنة يحرسها الحارس.</p><div class="ex10-knight-board" id="ex10-knight-board"></div><div class="ex10-knight-status"><span>القفزات <b id="ex10-knight-count">٠ / ٨</b></span><span>الأختام <b id="ex10-knight-seals">٠ / ٣</b></span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-knight">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-knight">إعادة الاختبار</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){const cur=route[gameState.knightIndex],el=$('#ex10-knight-board',root);el.innerHTML=Array.from({length:6},(_,r)=>Array.from({length:6},(_,c)=>{const k=route.findIndex(p=>p[0]===r&&p[1]===c),isOpen=k>=0,isCurrent=isOpen&&k===gameState.knightIndex,isGoal=k===8,isSeal=sealSet.has(k),visited=isOpen&&k<gameState.knightIndex;return `<button class="ex10-knight-cell ${isOpen?'open':'blocked'} ${isCurrent?'current':''} ${isGoal?'goal':''} ${isSeal?'seal':''} ${visited?'visited':''}" ${isOpen?'data-knight="'+k+'"':''} ${isOpen?'':'disabled'} aria-label="${isOpen?'مربع مسار '+ar(k+1):'مربع مغلق'}">${isCurrent?'♞':isGoal?'🚪':isSeal?'✦':visited?'✓':''}</button>`;}).join('')).join('');$('#ex10-knight-count',root).textContent=ar(gameState.knightMoves)+' / ٨';$('#ex10-knight-seals',root).textContent=ar(gameState.knightSeals.length)+' / ٣';el.querySelectorAll('[data-knight]').forEach(b=>b.onclick=()=>{const k=+b.dataset.knight;if(gameState.finished||k===gameState.knightIndex)return;const from=route[gameState.knightIndex],to=route[k];if(!L.isKnightMove(from,to)){feedback('هذه ليست قفزة فارس قانونية.','bad');return;}gameState.knightTrail.push({index:gameState.knightIndex,moves:gameState.knightMoves,seals:gameState.knightSeals.slice()});gameState.knightIndex=k;gameState.knightMoves++;if(sealSet.has(k)&&!gameState.knightSeals.includes(k))gameState.knightSeals.push(k);paint();if(k===8){if(gameState.knightMoves===8&&gameState.knightSeals.join('|')==='2|4|7')winStage(i,'جمعت الأختام الثلاثة بالترتيب ووصل الفارس إلى بوابة قصر المرايا في ثماني قفزات.');else failStage(i,'وصل الفارس إلى البوابة، لكن ترتيب الأختام أو عدد القفزات غير صحيح.');return;}if(gameState.knightMoves>=8)failStage(i,'انتهت القفزات الثماني قبل الوصول إلى البوابة. راجع المسار والأختام.');else feedback('قفزة قانونية. تابع نحو الختم التالي دون تجاوز ترتيبه.','good');});}
 root.querySelector('[data-ex10="undo-knight"]').onclick=()=>{if(gameState.finished||!gameState.knightTrail.length)return;const p=gameState.knightTrail.pop();gameState.knightIndex=p.index;gameState.knightMoves=p.moves;gameState.knightSeals=p.seals;paint();feedback('تراجعت خطوة؛ لم تحتسب قفزة جديدة.','');};
 root.querySelector('[data-ex10="reset-knight"]').onclick=()=>{gameState.knightIndex=0;gameState.knightMoves=0;gameState.knightTrail=[];gameState.knightSeals=[];paint();feedback('عاد الفارس إلى نقطة البداية.','');};paint();
}


// Stage 21 — lantern maze with four dead-end niches and one simple start-to-exit route.
function gameLanternMaze(i){
 const start=L.mazePath[0],goal=L.mazePath[L.mazePath.length-1],open=new Set(L.mazeOpen.map(p=>p.join(',')));
 gameState.mazePath=[start.slice()];gameState.mazeMoves=0;gameState.mazeTrail=[];
 const board=`<p class="ex10-objective">اختر خانة مجاورة لموقعك الحالي. الممرات الجانبية لا تصل إلى البوابة؛ يمكنك التراجع خطوة أو إعادة المتاهة من البداية.</p><div class="ex10-maze-board" id="ex10-maze-board"></div><div class="ex10-maze-status"><span>الخطوات <b id="ex10-maze-count">٠ / ١٢</b></span><span>الموقع: <b id="ex10-maze-position">البداية</b></span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-maze">تراجع خطوة</button><button class="ex10-btn secondary" data-ex10="reset-maze">إعادة المتاهة</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){const cur=gameState.mazePath.at(-1),el=$('#ex10-maze-board',root);el.innerHTML=Array.from({length:7},(_,r)=>Array.from({length:7},(_,c)=>{const k=[r,c].join(','),isOpen=open.has(k),isStart=r===start[0]&&c===start[1],isGoal=r===goal[0]&&c===goal[1],visited=gameState.mazePath.some(p=>p[0]===r&&p[1]===c),current=cur[0]===r&&cur[1]===c;return isOpen?`<button class="ex10-maze-cell open ${visited?'visited':''} ${current?'current':''} ${isStart?'start':''} ${isGoal?'goal':''}" data-maze="${r},${c}" aria-label="${isStart?'البداية':isGoal?'المخرج':'ممر مضاء'}">${current?'🧭':isStart?'⚓':isGoal?'🚪':visited?'✦':'·'}</button>`:`<div class="ex10-maze-cell wall" aria-hidden="true"></div>`;}).join('')).join('');$('#ex10-maze-count',root).textContent=ar(gameState.mazeMoves)+' / ١٢';$('#ex10-maze-position',root).textContent=cur.join(',')===start.join(',')?'البداية':cur.join(',')===goal.join(',')?'المخرج':'ممر الحديقة';el.querySelectorAll('[data-maze]').forEach(b=>b.onclick=()=>step(b.dataset.maze.split(',').map(Number)));}
 function step(next){if(gameState.finished)return;const cur=gameState.mazePath.at(-1),adj=Math.abs(cur[0]-next[0])+Math.abs(cur[1]-next[1])===1,k=next.join(',');if(!adj||!open.has(k)){feedback('اختر ممراً مفتوحاً يلامس موقعك الحالي فقط.','bad');return;}if(gameState.mazePath.length>1&&gameState.mazePath.at(-2).join(',')===k){gameState.mazePath.pop();gameState.mazeMoves=Math.max(0,gameState.mazeMoves-1);paint();feedback('رجعت خطوة إلى الممر السابق.','');return;}if(gameState.mazePath.some(p=>p.join(',')===k)){feedback('زرت هذا الممر بالفعل؛ لا تحتاج إلى الدوران حوله.','bad');return;}gameState.mazeTrail.push(gameState.mazePath.map(p=>p.slice()));gameState.mazePath.push(next);gameState.mazeMoves++;paint();if(next.join(',')===goal.join(',')){const a=L.mazeAudit(),same=JSON.stringify(gameState.mazePath)===JSON.stringify(a.path);if(same)winStage(i,'وصلت البطلات إلى البوابة عبر المسار الوحيد في حديقة الفوانيس.');else failStage(i,'وصلت إلى المخرج بمسار غير معتمد؛ أعد قراءة الممرات واستخدم الطريق الأقصر الوحيد.');return;}if(gameState.mazeMoves>=18)failStage(i,'تجاوزت خطوات المتاهة المسموحة دون الوصول إلى المخرج.');else if(L.mazeBranches.some(p=>p.join(',')===k)){gameState.errors++;feedback('هذا جيب جانبي ينتهي عند جدار. تراجع إلى آخر تقاطع.','bad');}else feedback('فانوس الطريق أضاء؛ تابع إلى الممر المجاور.','good');}
 root.querySelector('[data-ex10="undo-maze"]').onclick=()=>{if(gameState.finished||gameState.mazePath.length<=1)return;gameState.mazePath.pop();gameState.mazeMoves=Math.max(0,gameState.mazeMoves-1);paint();feedback('تراجعت إلى الممر السابق.','');};
 root.querySelector('[data-ex10="reset-maze"]').onclick=()=>{gameState.mazePath=[start.slice()];gameState.mazeMoves=0;gameState.mazeTrail=[];paint();feedback('أعيدت المتاهة إلى نقطة البداية.','');};paint();
}

// Stage 22 — two water jugs; legal fill, empty and pour actions only.
function gameWaterJugs(i){
 gameState.jugs=L.jugStart.slice();gameState.jugMoves=0;gameState.jugTrail=[];
 const actions=[['fillA','املأ الكبير'],['fillB','املأ الصغير'],['pourBtoA','اسكب الصغير ← الكبير'],['pourAtoB','اسكب الكبير ← الصغير'],['emptyA','أفرغ الكبير'],['emptyB','أفرغ الصغير']];
 const board=`<p class="ex10-objective">الحوض الكبير سعته ٧ وحدات والصغير سعته ٤. استخدم التعبئة والإفراغ والسكب بينهما حتى تحصل على ٥ وحدات في الكبير. الحل الأقصر ثماني عمليات.</p><div class="ex10-jugs" id="ex10-jugs"></div><div class="ex10-jug-actions">${actions.map(([id,label])=>`<button class="ex10-btn secondary" data-jug="${id}">${label}</button>`).join('')}</div><div class="ex10-jug-status"><span>العمليات <b id="ex10-jug-count">٠ / ٨</b></span><span>المطلوب: ٥ / ٧ في الحوض الكبير</span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-jug">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-jug">إعادة الأحواض</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){const [a,b]=gameState.jugs;$('#ex10-jugs',root).innerHTML=[[a,7,'الحوض الكبير','A'],[b,4,'الحوض الصغير','B']].map(([v,cap,label,id])=>`<div class="ex10-jug ${id==='A'?'large':''}"><b>${label}</b><div class="ex10-jug-glass"><div class="ex10-jug-water" style="height:${v/cap*100}%"></div><span>${ar(v)} / ${ar(cap)}</span></div><small>${v===cap?'ممتلئ':v===0?'فارغ':'كمية الماء'}</small></div>`).join('');$('#ex10-jug-count',root).textContent=ar(gameState.jugMoves)+' / ٨';root.querySelectorAll('[data-jug]').forEach(b=>b.disabled=gameState.finished);}
 function act(id){if(gameState.finished)return;const next=L.jugNext(gameState.jugs).find(x=>x.action===id);if(!next){feedback('هذه العملية لا تغيّر كمية الماء في الوضع الحالي. اختر تعبئة أو سكْباً له أثر.','bad');gameState.errors++;return;}gameState.jugTrail.push(gameState.jugs.slice());gameState.jugs=next.state;gameState.jugMoves++;gameState.moves++;paint();if(gameState.jugs[0]===5){if(gameState.jugMoves===8&&gameState.jugs[1]===0)winStage(i,'استقرت خمس وحدات بالضبط في الحوض الكبير عبر التسلسل الأقصر الوحيد ذي العمليات الثماني.');else failStage(i,'وصلت إلى الكمية المطلوبة، لكن ليس عبر التسلسل الأقصر ذي العمليات الثماني. أعد المحاولة بخطة القياس المثبتة.');return;}if(gameState.jugMoves>=8)failStage(i,'استهلكت العمليات الثماني دون الحصول على خمس وحدات في الحوض الكبير.');else feedback(next.label+'؛ أصبح في الحوضين '+ar(gameState.jugs[0])+' و'+ar(gameState.jugs[1])+' وحدات.','good');}
 root.querySelectorAll('[data-jug]').forEach(b=>b.onclick=()=>act(b.dataset.jug));
 root.querySelector('[data-ex10="undo-jug"]').onclick=()=>{if(gameState.finished||!gameState.jugTrail.length)return;gameState.jugs=gameState.jugTrail.pop();gameState.jugMoves=Math.max(0,gameState.jugMoves-1);paint();feedback('أعدت كمية الماء إلى الوضع السابق.','');};
 root.querySelector('[data-ex10="reset-jug"]').onclick=()=>{gameState.jugs=L.jugStart.slice();gameState.jugMoves=0;gameState.jugTrail=[];paint();feedback('الحوضان فارغان من جديد.','');};paint();
}

// Stage 23 — Lights Out signal grid: tap a tower to toggle itself and orthogonal neighbours.
function gameSignalTowers(i){
 gameState.signalBoard=L.signalStart.slice();gameState.signalClicks=[];gameState.signalTrail=[];
 const board=`<p class="ex10-objective">كل ضغطة تبدّل إشارة البرج نفسه والأبراج المتصلة به أفقياً ورأسياً فقط. أطفئ الأضواء التسعة بأربع ضغطات، ولا تؤثر الضغطة في الأبراج القطرية.</p><div class="ex10-signal-board" id="ex10-signal-board"></div><div class="ex10-signal-status"><span>الضغطات <b id="ex10-signal-count">٠ / ٤</b></span><span>الأبراج المضيئة <b id="ex10-signal-lit">٦</b></span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-signal">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-signal">إعادة الإشارات</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function paint(){const el=$('#ex10-signal-board',root);el.innerHTML=gameState.signalBoard.map((v,k)=>`<button class="ex10-signal-cell ${v?'lit':'dark'}" data-signal="${k}" aria-label="البرج ${ar(k+1)} ${v?'مضيء':'مطفأ'}">${v?'✦':'◇'}</button>`).join('');$('#ex10-signal-count',root).textContent=ar(gameState.signalClicks.length)+' / ٤';$('#ex10-signal-lit',root).textContent=ar(gameState.signalBoard.reduce((a,v)=>a+v,0));el.querySelectorAll('[data-signal]').forEach(b=>b.onclick=()=>tap(+b.dataset.signal));}
 function tap(k){if(gameState.finished)return;gameState.signalTrail.push({board:gameState.signalBoard.slice(),clicks:gameState.signalClicks.slice()});gameState.signalBoard=L.signalApply([k],gameState.signalBoard);gameState.signalClicks.push(k);gameState.moves++;paint();if(gameState.signalBoard.every(v=>v===0)){const wanted=L.signalSolution.slice().sort((a,b)=>a-b),actual=gameState.signalClicks.slice().sort((a,b)=>a-b);if(gameState.signalClicks.length===4&&JSON.stringify(actual)===JSON.stringify(wanted))winStage(i,'انطفأت الأبراج التسعة بأربع ضغطات وفق مجموعة الحل الوحيدة.');else failStage(i,'انطفأت الشبكة، لكنك استخدمت مجموعة ضغطات أو عدداً مختلفاً عن الحل الأدنى. أعد المحاولة.');return;}if(gameState.signalClicks.length>=4)failStage(i,'انتهت الضغطات الأربع وما زالت بعض الأبراج مضيئة.');else feedback('تبدلت إشارة البرج وجيرانه المباشرين. راقب أثر الضغط على الشبكة كلها.','good');}
 root.querySelector('[data-ex10="undo-signal"]').onclick=()=>{if(gameState.finished||!gameState.signalTrail.length)return;const p=gameState.signalTrail.pop();gameState.signalBoard=p.board;gameState.signalClicks=p.clicks;paint();feedback('ألغيت أثر الضغطة الأخيرة.','');};
 root.querySelector('[data-ex10="reset-signal"]').onclick=()=>{gameState.signalBoard=L.signalStart.slice();gameState.signalClicks=[];gameState.signalTrail=[];paint();feedback('عادت الأبراج إلى حالتها الأولى.','');};paint();
}

// Stage 24 — three-disk Towers of Hanoi with strict top-disk and size rules.
function gameHanoi(i){
 gameState.hanoi=L.hanoiStart.slice();gameState.hanoiMoves=0;gameState.hanoiSelected=-1;gameState.hanoiTrail=[];
 const board=`<p class="ex10-objective">انقل الأقراص الثلاثة من العمود الأول إلى العمود الثالث. لا تنقل إلا القرص الموجود أعلى العمود، ولا تضع قرصاً كبيراً فوق قرص أصغر. أكمل بأقصر حل: سبع نقلات.</p><div class="ex10-hanoi-board" id="ex10-hanoi-board"></div><div class="ex10-hanoi-status"><span>النقلات <b id="ex10-hanoi-count">٠ / ٧</b></span><span>اختر عمود المصدر ثم عمود الوجهة</span></div><div class="ex10-controls"><button class="ex10-btn secondary" data-ex10="undo-hanoi">تراجع</button><button class="ex10-btn secondary" data-ex10="reset-hanoi">إعادة الأقراص</button></div>`;
 root.innerHTML=commonGame(i,board);bindCommon(i);
 function pegHtml(peg){const disks=gameState.hanoi.map((p,d)=>p===peg?d:-1).filter(d=>d>=0).sort((a,b)=>b-a);return `<button class="ex10-hanoi-peg ${gameState.hanoiSelected===peg?'selected':''}" data-hanoi-peg="${peg}"><b>العمود ${['أ','ب','ج'][peg]}</b><div class="ex10-hanoi-stack">${[2,1,0].map(d=>disks.includes(d)?`<span class="disk disk-${d}">${ar(d+1)}</span>`:`<span class="disk-space"></span>`).join('')}</div><small>${gameState.hanoiSelected===peg?'مصدر محدد':'اختر العمود'}</small></button>`;}
 function paint(){const el=$('#ex10-hanoi-board',root);el.innerHTML=[0,1,2].map(peg=>pegHtml(peg)).join('');$('#ex10-hanoi-count',root).textContent=ar(gameState.hanoiMoves)+' / ٧';el.querySelectorAll('[data-hanoi-peg]').forEach(b=>b.onclick=()=>choose(+b.dataset.hanoiPeg));}
 function choose(peg){if(gameState.finished)return;if(gameState.hanoiSelected<0){if(!gameState.hanoi.includes(peg)){feedback('هذا العمود فارغ؛ اختر عموداً يحتوي قرصاً.','bad');return;}gameState.hanoiSelected=peg;paint();return;}const from=gameState.hanoiSelected;if(from===peg){gameState.hanoiSelected=-1;paint();return;}const moving=gameState.hanoi.map((p,d)=>p===from?d:-1).filter(d=>d>=0).sort((a,b)=>a-b)[0],topDest=gameState.hanoi.map((p,d)=>p===peg?d:-1).filter(d=>d>=0).sort((a,b)=>a-b)[0];if(topDest!==undefined&&topDest<moving){feedback('لا يمكن وضع قرص كبير فوق قرص أصغر.','bad');gameState.errors++;gameState.hanoiSelected=-1;paint();return;}gameState.hanoiTrail.push({state:gameState.hanoi.slice(),moves:gameState.hanoiMoves});gameState.hanoi[moving]=peg;gameState.hanoiMoves++;gameState.moves++;gameState.hanoiSelected=-1;paint();if(gameState.hanoi.every(p=>p===2)){if(gameState.hanoiMoves===7&&L.hanoiAudit().count===1)winStage(i,'انتقلت الأقراص الثلاثة إلى العمود الأخير في سبع نقلات قانونية، وهو أقصر تسلسل وحيد.');else failStage(i,'وصلت الأقراص بعد عدد نقلات أكثر من الحل الأقصر. أعد المحاولة بخطة سبع نقلات.');return;}if(gameState.hanoiMoves>=7)failStage(i,'انتهت النقلات السبع قبل اكتمال نقل الأقراص.');else feedback('نقلة قانونية؛ أصبح القرص في العمود الجديد. خطط للقرص الأكبر قبل تحريكه.','good');}
 root.querySelector('[data-ex10="undo-hanoi"]').onclick=()=>{if(gameState.finished||!gameState.hanoiTrail.length)return;const p=gameState.hanoiTrail.pop();gameState.hanoi=p.state;gameState.hanoiMoves=p.moves;gameState.hanoiSelected=-1;paint();feedback('عاد القرص إلى العمود السابق.','');};
 root.querySelector('[data-ex10="reset-hanoi"]').onclick=()=>{gameState.hanoi=L.hanoiStart.slice();gameState.hanoiMoves=0;gameState.hanoiSelected=-1;gameState.hanoiTrail=[];paint();feedback('عادت الأقراص إلى العمود الأول.','');};paint();
}

// Stage 25 — arrange five unique runes according to four positional clues.
function gameFivefoldSeal(i){
 const runes=L.sealRunes;gameState.sealOrder=[null,null,null,null,null];
 const clues=`<div class="mk-clues ex10-mk-clues"><div class="mk-clue">${mxChip('قمر','قمر',1)}${mxRel('مباشرة قبل')}${mxChip('ورقة','ورقة',1)}</div><div class="mk-clue">${mxChip('ورقة','ورقة',1)}${mxRel('قبل')}${mxChip('ماء','ماء',1)}</div><div class="mk-clue">${mxChip('نجمة','نجمة',1)}${mxRel('بعد')}${mxChip('ماء','ماء',1)}</div><div class="mk-clue">${mxChip('نار','نار',1)}${mxRel('=')}${mxSlotMark(5)}</div></div>`;
 root.innerHTML=commonGame(i,`<p class="ex10-objective">اسحب الأختام إلى الخانات من اليسار إلى اليمين. كل رمز مرة واحدة.</p>${clues}<div class="mk-board ex10-mk" id="ex10-seal"></div><div class="ex10-controls"><button class="ex10-btn" data-ex10="check-seal">تثبيت الختم</button><button class="ex10-btn secondary" data-ex10="reset-seal">إعادة الرموز</button></div>`);bindCommon(i);
 const host=$('#ex10-seal',root),board=mxOrderBoard(host,runes,k=>k,gameState.sealOrder,()=>{},{ltr:true,slotName:q=>'الخانة '+ar(q+1)});
 gameState.solve=()=>board.set(L.audit().seal[0]);
 root.querySelector('[data-ex10="check-seal"]').onclick=()=>{const vals=gameState.sealOrder;if(vals.some(x=>!x)){feedback('ضع رمزًا في كل خانة أولًا.','bad');return;}if(L.sealValid(vals)){winStage(i,'اصطف القمر والورقة والماء والنجمة والنار بالترتيب الوحيد، وانفتح محراب أَثْران.');return;}gameState.errors++;feedback('الختم لم يستجب. انظر إلى النقش الذي يخالفه ترتيبك.','bad');updateCrew(['thinking','curious','alert'],['رواء','القرائن مترابطة؛ لنختبر ترتيباً يحققها جميعاً.']);};
 root.querySelector('[data-ex10="reset-seal"]').onclick=()=>{gameState.sealOrder.fill(null);board.paint();feedback('عادت الرموز إلى الصينية.','');};
}

// The expedition module is an additive chapter, not a replacement for the existing campaigns.
preloadCrewPoses();
